INSERT INTO "bounties" ("id", "title_en", "title_ar", "description_en", "description_ar", "source", "points", "term_id", "node_id", "status", "posted_by", "fulfilled_by", "fulfilled_resource_type", "fulfilled_resource_id", "created_at", "updated_at") VALUES
('01M4D6BHRTD7P332XD8W73BJ61', 'Document the water tariff review methodology', 'توثيق منهجية مراجعة تعرفة المياه', 'Write up how the municipal water tariff structure was last reviewed, including sources and assumptions.', 'أعدّ توثيقاً لكيفية مراجعة هيكل تعرفة المياه البلدية مؤخراً، بما في ذلك المصادر والافتراضات.', 'gap_radar', 100, '01M4D6BGDY3NKBWBTR3SZKJFVZ', NULL, 'open', '01M4D6BGHA1ANAZV0TK6CR8SAW', NULL, NULL, NULL, '2026-10-08T07:23:58.764Z', '2026-10-08T07:23:58.764Z'),
('01M4D6BHRT8NMEBF8S7E2MC31K', 'Upload the earlier cycle final results report', 'رفع تقرير النتائج النهائية للدورة السابقة', 'Locate and upload the final evaluation report of the earlier environment sector programme so lessons can inform delivery.', 'حدّد ورفع التقرير النهائي لتقييم برنامج قطاع البيئة السابق حتى تفيد دروسه في التنفيذ.', 'manual', 80, '01M4D6BGE1BBA6FDV8PP1E62RQ', NULL, 'open', '01M4D6BGHA1ANAZV0TK6CR8SAW', NULL, NULL, NULL, '2026-10-08T07:23:58.764Z', '2026-10-08T07:23:58.764Z'),
('01M4D6BHRTN4HWY8ZNXGAP36HA', 'Capture lessons from the household water survey', 'استخلاص الدروس من مسح المياه الأسري', 'Interview field coordinators and summarise what worked and what did not during household water survey collection.', 'قابل منسقي العمل الميداني ولخّص ما نجح وما لم ينجح أثناء جمع بيانات مسح المياه الأسري.', 'gap_radar', 120, '01M4D6BGDV02SRE6JE5JW5FATZ', NULL, 'open', '01M4D6BGHA1ANAZV0TK6CR8SAW', NULL, NULL, NULL, '2026-10-08T07:23:58.764Z', '2026-10-08T07:23:58.764Z'),
('01M4D6BHRTS0X1KMQ8KRXPV8SP', 'Map data sharing agreements across regulators', 'حصر اتفاقيات تبادل البيانات بين الجهات التنظيمية', 'Compile a list of active data sharing agreements between environmental regulators and flag any that need renewal.', 'أعدّ قائمة باتفاقيات تبادل البيانات القائمة بين الجهات التنظيمية البيئية ونبّه إلى ما يحتاج إلى تجديد.', 'gap_radar', 90, '01M4D6BGDR05ABXF3243AV15WP', NULL, 'open', '01M4D6BGHA1ANAZV0TK6CR8SAW', NULL, NULL, NULL, '2026-10-08T07:23:58.764Z', '2026-10-08T07:23:58.764Z'),
('01M4D6BHRTCZ61R1J6K3R4Y92A', 'Summarise the data standards for new users', 'تلخيص معايير البيانات للمستخدمين الجدد', 'Produce a plain-language summary of the data standards that environmental datasets must follow, for new EnviroAI users.', 'أعدّ ملخصاً بلغة مبسطة لمعايير البيانات التي يجب أن تتبعها مجموعات البيانات البيئية للمستخدمين الجدد في EnviroAI.', 'manual', 70, '01M4D6BGDR05ABXF3243AV15WP', NULL, 'open', '01M4D6BGHA1ANAZV0TK6CR8SAW', NULL, NULL, NULL, '2026-10-08T07:23:58.764Z', '2026-10-08T07:23:58.764Z'),
('01M4D6BHRVJB3Y2TYCWQ4H3H8K', 'Document the open data publication checklist', 'توثيق قائمة التحقق لنشر البيانات المفتوحة', 'Write the step-by-step checklist a team should follow before publishing a new dataset on the open data portal.', 'اكتب قائمة التحقق خطوة بخطوة التي ينبغي أن يتبعها الفريق قبل نشر مجموعة بيانات جديدة على بوابة البيانات المفتوحة.', 'gap_radar', 60, '01M4D6BGDS33VK7Q2NMW5ZDH2V', NULL, 'open', '01M4D6BGHA1ANAZV0TK6CR8SAW', NULL, NULL, NULL, '2026-10-08T07:23:58.764Z', '2026-10-08T07:23:58.764Z'),
('01M4D6BHRVCBC2D6W5N6ZQ3801', 'Explain how the Environmental Performance Index scores countries', 'شرح كيفية تقييم مؤشر الأداء البيئي للدول', 'Explain how the Yale Environmental Performance Index scores countries and which indicators most affect the Kingdom''s position.', 'اشرح كيف يقيّم مؤشر الأداء البيئي الصادر عن جامعة ييل الدول وأي المؤشرات أشد أثراً في موقع المملكة.', 'manual', 75, '01M4D6BGE5RTW50W8T2R7EH8WK', NULL, 'open', '01M4D6BGHA1ANAZV0TK6CR8SAW', NULL, NULL, NULL, '2026-10-08T07:23:58.764Z', '2026-10-08T07:23:58.764Z'),
('01M4D6BHRVZ0QJF5DKG9CHXT2C', 'Draft an early warning indicator for groundwater stress', 'صياغة مؤشر إنذار مبكر لإجهاد المياه الجوفية', 'Propose a leading indicator that could flag aquifer stress before it shows up in abstraction statistics.', 'اقترح مؤشراً استباقياً يمكنه الإنذار بإجهاد الخزانات الجوفية قبل ظهوره في إحصاءات السحب.', 'gap_radar', 130, '01M4D6BGE2SEQ1ENWH3Y2FDNRQ', NULL, 'open', '01M4D6BGHA1ANAZV0TK6CR8SAW', NULL, NULL, NULL, '2026-10-08T07:23:58.764Z', '2026-10-08T07:23:58.764Z'),
('01M4D6BHRV5ZF03QM9TP5XQNBH', 'Compile lessons from prior scenario planning exercises', 'تجميع الدروس من تمارين تخطيط السيناريوهات السابقة', 'Review past foresight workshops and summarise which scenarios materialised and which assumptions need updating.', 'راجع ورش الاستشراف السابقة ولخّص السيناريوهات التي تحققت والافتراضات التي تحتاج إلى تحديث.', 'gap_radar', 110, '01M4D6BGE2S60C36R9EFVM7EY4', NULL, 'open', '01M4D6BGHA1ANAZV0TK6CR8SAW', NULL, NULL, NULL, '2026-10-08T07:23:58.764Z', '2026-10-08T07:23:58.764Z'),
('01M4D6BHRVH6JEBQHEHM672RHM', 'Verify the Arabic translation of the regulatory glossary', 'مراجعة الترجمة العربية للمسرد التنظيمي', 'Review the machine-translated Arabic glossary of environmental regulatory terms and correct any inaccurate terminology.', 'راجع المسرد العربي المترجم آلياً للمصطلحات التنظيمية البيئية وصحّح أي مصطلح غير دقيق.', 'manual', 50, '01M4D6BGEAJ1WRFV0NAEH82VH5', NULL, 'open', '01M4D6BGHA1ANAZV0TK6CR8SAW', NULL, NULL, NULL, '2026-10-08T07:23:58.764Z', '2026-10-08T07:23:58.764Z');
