INSERT INTO "council_alignment" ("id", "council_node_id", "target_kind", "target_id", "label_en", "label_ar", "note_en", "note_ar") VALUES
('01M4D6CB0F9MW2GNJD9SZQB9TY', '01M4D6CAY625SEB1WV3KN64N2M', 'nes_node', '01M4D6BHK9NM2DQJ5JEAEJ758J', 'Regulatory Compliance', 'الامتثال التنظيمي', 'A single planning standard and quality assured reviews keep entity plans consistent with the regulatory framework they must deliver under, and make gaps visible early.', 'يحافظ توحيد معيار التخطيط ومراجعات ضمان الجودة على اتساق خطط الجهات مع الإطار التنظيمي الذي تنفذ في ظله، ويكشف الفجوات مبكراً.'),
('01M4D6CB0FJZWX7XYDP0M0QQ4Z', '01M4D6CAY625SEB1WV3KN64N2M', 'nes_node', '01M4D6BHK9576VE73AKHSCPJCR', 'Water Security', 'الأمن المائي', 'Water initiatives reach their targets faster when their plans are properly specified and when simulation exposes weak assumptions before money is committed.', 'تبلغ مبادرات المياه مستهدفاتها بوتيرة أسرع حين تكون خططها محددة بدقة وحين تكشف المحاكاة الافتراضات الضعيفة قبل الالتزام بالإنفاق.'),
('01M4D6CB0F5A0M2QQWHWYYMY03', '01M4D6CAY625SEB1WV3KN64N2M', 'nes_node', '01M4D6BHK9K95DGK4RSBSQKWH0', 'Agriculture and Food Security', 'الأمن الغذائي والزراعة', 'Testing policies before adoption and linking plans to costed outputs reduces spending on initiatives that would not have produced the intended result for farming and food systems.', 'يقلّص اختبار السياسات قبل اعتمادها وربط الخطط بمخرجات مُكلّفة الإنفاقَ على مبادرات ما كانت لتحقق النتيجة المقصودة للمزارع والنظم الغذائية.'),
('01M4D6CB0F3S1ZZ3CWQBP9N5SN', '01M4D6CAY6R3SYHXXXG7N8R26H', 'nes_node', '01M4D6BHK985WAR19CDE822C55', 'Climate and Environment', 'المناخ والبيئة', 'Trusted emissions, land and environmental condition data is the base for climate reporting and for tracking environmental commitments.', 'تشكل بيانات الانبعاثات والأراضي والأحوال البيئية الموثوقة القاعدة للإبلاغ المناخي ولمتابعة الالتزامات البيئية.'),
('01M4D6CB0FGHJZNVQHP5C2YF8C', '01M4D6CAY6R3SYHXXXG7N8R26H', 'data_strategy_initiative', 'environmental-data-strategy', 'Environmental Data Strategy', 'استراتيجية البيانات البيئية', 'Data governance, sharing agreements, a unified catalogue and quality standards are the core of the environmental data strategy and are delivered through this goal.', 'تشكل حوكمة البيانات واتفاقيات المشاركة والفهرس الموحد ومعايير الجودة جوهر استراتيجية البيانات البيئية، وتُنفَّذ عبر هذا الهدف.'),
('01M4D6CB0FM989Y0EBWX8HRX0C', '01M4D6CAY6R3SYHXXXG7N8R26H', 'nes_node', '01M4D6BHK9576VE73AKHSCPJCR', 'Water Security', 'الأمن المائي', 'Consistent water supply, demand and quality data lets the water theme be steered on shared figures instead of entity by entity estimates.', 'تتيح بيانات العرض والطلب وجودة المياه المتسقة توجيه محور المياه بأرقام مشتركة بدل تقديرات كل جهة على حدة.'),
('01M4D6CB0FYPQ80Z0N2DD8DH4Q', '01M4D6CAY743SM5Q85A348YH1Q', 'nes_node', '01M4D6BHK985WAR19CDE822C55', 'Climate and Environment', 'المناخ والبيئة', 'Early signals on climate impacts and environmental pressure give the climate theme time to adapt its plans before shocks arrive.', 'تمنح الإشارات المبكرة عن الآثار المناخية والضغوط البيئية محور المناخ وقتاً لتكييف خططه قبل وقوع الصدمات.'),
('01M4D6CB0FSZXJ7SW013R14W8E', '01M4D6CAY743SM5Q85A348YH1Q', 'nes_node', '01M4D6BHK9ZC3FQM79EBENHZZS', 'Biodiversity and Land', 'التنوع الأحيائي والأراضي', 'Scenarios on land degradation, desertification and habitat pressure help the land and biodiversity theme choose where to act first.', 'تساعد السيناريوهات عن تدهور الأراضي والتصحر وضغوط الموائل محور الأراضي والتنوع الأحيائي على اختيار مواضع التدخل الأولى.'),
('01M4D6CB0GP8YHGQKYXAG962SA', '01M4D6CAY743SM5Q85A348YH1Q', 'nes_node', '01M4D6BHK9906RXCKJDEFHHBAC', 'Air Quality', 'جودة الهواء', 'Horizon scanning on emission sources and exposure trends supports earlier action on air quality.', 'يدعم مسح الأفق لمصادر الانبعاثات واتجاهات التعرض اتخاذ إجراءات أبكر بشأن جودة الهواء.'),
('01M4D6CB0G43TGWQZCS5CNPS1Z', '01M4D6CAY7TCCG4N0FGRMJ7VEW', 'nes_node', '01M4D6BHK9NM2DQJ5JEAEJ758J', 'Regulatory Compliance', 'الامتثال التنظيمي', 'A current regulatory register and change tracking is the working core of the regulatory compliance theme.', 'يشكل السجل التنظيمي المحدّث وتتبع التغييرات الجوهر العملي لمحور الامتثال التنظيمي.'),
('01M4D6CB0G6RPM26MYWRHRSPK1', '01M4D6CAY7TCCG4N0FGRMJ7VEW', 'nes_node', '01M4D6BHK98RDWCXHQPEBWMYRK', 'Waste and Circular Economy', 'النفايات والاقتصاد الدائري', 'Clear and findable rules on waste and recycling help entities and operators comply and help the Office see where requirements overlap or conflict.', 'تساعد القواعد الواضحة وسهلة الاسترجاع بشأن النفايات وإعادة التدوير الجهات والمشغّلين على الامتثال، وتُظهر للمكتب مواضع تداخل المتطلبات أو تعارضها.'),
('01M4D6CB0GF0H8SKC7Z7WV005X', '01M4D6CAY7TCCG4N0FGRMJ7VEW', 'data_strategy_initiative', 'environmental-data-strategy', 'Environmental Data Strategy', 'استراتيجية البيانات البيئية', 'Unified digital platforms and data driven performance reporting are the internal systems on which the environmental data strategy runs.', 'تشكل المنصات الرقمية الموحدة وتقارير الأداء القائمة على البيانات النظم الداخلية التي تقوم عليها استراتيجية البيانات البيئية.'),
('01M4D6CB0G0469PAF6VS3TBPE0', '01M4D6CAY7TXWV9CV7FGPGC1QJ', 'nes_node', '01M4D6BHK985WAR19CDE822C55', 'Climate and Environment', 'المناخ والبيئة', 'International cooperation and consistent public messages support the Kingdom''s climate and environmental commitments and its standing in global reporting.', 'يدعم التعاون الدولي والرسائل العامة المتسقة التزامات المملكة المناخية والبيئية ومكانتها في الإبلاغ العالمي.'),
('01M4D6CB0G1QRNCTD1FMDHN8NE', '01M4D6CAY7TXWV9CV7FGPGC1QJ', 'nes_node', '01M4D6BHK9576VE73AKHSCPJCR', 'Water Security', 'الأمن المائي', 'Research and international partnerships bring methods and benchmarks that water entities can use for planning and demand management.', 'تجلب الشراكات البحثية والدولية منهجيات ومرجعيات تستفيد منها جهات المياه في التخطيط وإدارة الطلب.'),
('01M4D6CB0GWH8P0VAE14EA47B2', '01M4D6CAY7TXWV9CV7FGPGC1QJ', 'nes_node', '01M4D6BHK9K95DGK4RSBSQKWH0', 'Agriculture and Food Security', 'الأمن الغذائي والزراعة', 'Cooperation with international and academic partners brings evidence on sustainable farming and food systems into national planning.', 'يُدخل التعاون مع الشركاء الدوليين والأكاديميين أدلة عن الزراعة المستدامة والنظم الغذائية في التخطيط الوطني.');
INSERT INTO "council_analysis" ("id", "strategy_id", "kind", "payload_json", "sort") VALUES
('01M4D6CAY5KMP7NNKARM56T065', '01M4D6CAY5T0XKCNYRFK5B2F2D', 'swot', '[{"quadrant":"strength","textEn":"A clear mandate to steer the National Environment Strategy, which gives the Office standing to convene every entity in the sector around one plan.","textAr":"تكليف واضح بقيادة الاستراتيجية الوطنية للبيئة، يمنح المكتب الصفة التي تتيح له جمع جهات القطاع كافة حول خطة واحدة."},{"quadrant":"strength","textEn":"A dedicated data and knowledge sector that brings together environmental data affairs, data operations, systems, quality and governance under one roof.","textAr":"قطاع مخصص للبيانات والمعرفة يجمع شؤون البيانات البيئية وعمليات البيانات والنظم والجودة والحوكمة تحت مظلة واحدة."},{"quadrant":"strength","textEn":"A dedicated foresight and risk function, still uncommon in the sector, that connects Saudi Vision 2030 environmental work to live policy questions.","textAr":"وجود إدارة مخصصة للاستشراف والمخاطر، وهو أمر لا يزال نادراً في القطاع، تربط أعمال رؤية السعودية 2030 البيئية بالقضايا السياساتية الآنية."},{"quadrant":"strength","textEn":"A direct reporting line to the Programme Steering Committee, so analysis reaches the decision table without passing through intermediaries who reshape it.","textAr":"خط رفع مباشر إلى اللجنة التوجيهية للبرنامج، بما يتيح وصول التحليل إلى طاولة القرار دون وسطاء يعيدون صياغته."},{"quadrant":"strength","textEn":"An implementation support function that works inside entities on delivery problems rather than only collecting progress reports from them.","textAr":"وجود وظيفة لدعم التنفيذ تعمل داخل الجهات على معالجة مشكلات الإنجاز، لا على جمع تقارير التقدم منها فحسب."},{"quadrant":"weakness","textEn":"The monitoring picture depends on what entities submit, so the Office''s view of delivery is only as timely and complete as their returns.","textAr":"تعتمد صورة المتابعة على ما ترفعه الجهات، فلا تكون نظرة المكتب إلى الإنجاز أسرع أو أكمل من تقاريرها."},{"quadrant":"weakness","textEn":"Environmental data is produced on separate systems with uneven documentation, so combining water, agriculture, climate and waste figures still takes manual effort.","textAr":"تُنتج البيانات البيئية على نظم منفصلة وبتوثيق متفاوت، فيظل الجمع بين أرقام المياه والزراعة والمناخ والنفايات جهداً يدوياً."},{"quadrant":"weakness","textEn":"Knowledge sits with individuals and in personal folders, so a change of role can remove context that the next team needs.","textAr":"تتركز المعرفة لدى الأفراد وفي مجلدات شخصية، فقد يؤدي تغيير الدور إلى فقدان سياق يحتاجه الفريق التالي."},{"quadrant":"weakness","textEn":"Specialist skills in modelling, remote sensing and data science are concentrated in a few people, which limits how many initiatives can run in parallel.","textAr":"تتركز المهارات المتخصصة في النمذجة والاستشعار عن بعد وعلوم البيانات لدى قلة من الأفراد، مما يحدّ من عدد المبادرات التي تُنفَّذ بالتوازي."},{"quadrant":"weakness","textEn":"Regulatory changes reach the Office through informal channels, so impact on plans and indicators is often assessed after the fact.","textAr":"تصل التغييرات التنظيمية إلى المكتب عبر قنوات غير رسمية، فيجري تقدير أثرها على الخطط والمؤشرات في الغالب بعد وقوعها."},{"quadrant":"opportunity","textEn":"Growing national attention to water security, food security and climate commitments raises demand for a trusted, shared evidence base.","textAr":"يرفع تنامي الاهتمام الوطني بالأمن المائي والغذائي والالتزامات المناخية الطلب على قاعدة أدلة موثوقة ومشتركة."},{"quadrant":"opportunity","textEn":"Satellite imagery, sensor networks and open geospatial data make it possible to measure land, water and air conditions more often and at lower cost than field surveys alone.","textAr":"تتيح صور الأقمار الصناعية وشبكات المستشعرات والبيانات المكانية المفتوحة قياس أحوال الأراضي والمياه والهواء بوتيرة أعلى وتكلفة أقل من المسوح الميدانية وحدها."},{"quadrant":"opportunity","textEn":"Research capacity in Saudi universities and research centres offers a ready partner base for modelling, simulation and applied studies.","textAr":"توفر القدرات البحثية في الجامعات ومراكز الأبحاث السعودية قاعدة شركاء جاهزة للنمذجة والمحاكاة والدراسات التطبيقية."},{"quadrant":"opportunity","textEn":"Machine assisted search and summarisation can make the Office''s regulatory and institutional knowledge findable in seconds, with sources cited.","textAr":"يمكن للبحث والتلخيص بمساعدة الآلة أن يجعل المعرفة التنظيمية والمؤسسية للمكتب متاحة خلال ثوانٍ مع الإشارة إلى المصادر."},{"quadrant":"opportunity","textEn":"International reporting on sustainable development, climate and biodiversity is converging on common indicators, which lets one data effort serve several audiences.","textAr":"يتجه الإبلاغ الدولي عن التنمية المستدامة والمناخ والتنوع الأحيائي نحو مؤشرات مشتركة، مما يتيح لجهد بيانات واحد أن يخدم جهات متعددة."},{"quadrant":"threat","textEn":"Competing priorities among entities can push shared data and reporting duties down the agenda, leaving the national picture incomplete.","textAr":"قد تدفع الأولويات المتنافسة بين الجهات واجبات مشاركة البيانات والإبلاغ إلى مراتب متأخرة، فتبقى الصورة الوطنية ناقصة."},{"quadrant":"threat","textEn":"Competition for scarce data, modelling and digital talent from the private sector and giga projects makes retention difficult.","textAr":"تصعّب المنافسة على الكفاءات النادرة في البيانات والنمذجة والتقنية من القطاع الخاص والمشاريع الكبرى الاحتفاظَ بالمواهب."},{"quadrant":"threat","textEn":"A cyber incident or a data breach would damage trust in environmental data and could suspend shared services for a period.","textAr":"قد يضرّ حادث سيبراني أو اختراق للبيانات بالثقة في البيانات البيئية ويعلّق الخدمات المشتركة لفترة."},{"quadrant":"threat","textEn":"Unofficial or poorly sourced environmental figures circulate faster than official ones and can shape public debate before the Office responds.","textAr":"تنتشر الأرقام البيئية غير الرسمية أو ضعيفة التوثيق أسرع من الأرقام الرسمية، وقد تشكّل النقاش العام قبل أن يرد المكتب."},{"quadrant":"threat","textEn":"Climate and water shocks, such as prolonged drought or extreme heat, can force re-planning mid cycle and absorb capacity meant for long term work.","textAr":"قد تفرض الصدمات المناخية والمائية، كالجفاف الممتد أو الحرارة الشديدة، إعادة التخطيط في منتصف الدورة وتستنزف قدرات مخصصة لعمل طويل الأجل."}]', 0),
('01M4D6CAY6ZTD653DAZE4PMGTZ', '01M4D6CAY5T0XKCNYRFK5B2F2D', 'stakeholder', '[{"nameEn":"Programme Steering Committee","nameAr":"اللجنة التوجيهية للبرنامج","interest":5,"influence":5,"roleEn":"Approves the direction of the National Environment Strategy, receives its progress reports and decides on the policy options the Office puts forward. It is the primary audience for the delivery dashboard and the annual assessment.","roleAr":"تعتمد توجه الاستراتيجية الوطنية للبيئة وتتلقى تقارير تقدمها وتبت في خيارات السياسات التي يرفعها المكتب. وهي الجمهور الأول للوحة المتابعة التنفيذية وللتقييم السنوي."},{"nameEn":"Ministry of Environment, Water and Agriculture (MEWA)","nameAr":"وزارة البيئة والمياه والزراعة","interest":5,"influence":5,"roleEn":"Leads sector policy and holds much of the water, agriculture and environment data the Office relies on. Engagement is continuous, on strategy alignment, data sharing and delivery of shared initiatives.","roleAr":"تقود سياسات القطاع وتحتفظ بجانب كبير من بيانات المياه والزراعة والبيئة التي يعتمد عليها المكتب. والتفاعل معها مستمر في مواءمة الاستراتيجية ومشاركة البيانات وتنفيذ المبادرات المشتركة."},{"nameEn":"Environmental regulators and sector centres (NCEC, NCW, NCVC, MWAN)","nameAr":"الجهات التنظيمية والمراكز القطاعية البيئية (المركز الوطني للرقابة على الالتزام البيئي، المركز الوطني للحياة الفطرية، المركز الوطني لتنمية الغطاء النباتي ومكافحة التصحر، المركز الوطني لإدارة النفايات)","interest":4,"influence":4,"roleEn":"Own regulation, permitting, monitoring and enforcement within their mandates. They supply administrative records and regulatory changes and carry many of the outputs the strategy tracks.","roleAr":"تتولى التنظيم والترخيص والرصد والرقابة في نطاق اختصاصاتها. وتمد المكتب بالسجلات الإدارية والتغييرات التنظيمية وتنفذ كثيراً من المخرجات التي تتابعها الاستراتيجية."},{"nameEn":"Water sector entities (SWA, NWC)","nameAr":"جهات قطاع المياه (الهيئة السعودية للمياه، شركة المياه الوطنية)","interest":4,"influence":4,"roleEn":"Regulate and operate water supply, sanitation and reuse. They provide operational data for the water security theme and are central to demand and supply policy testing.","roleAr":"تنظم وتشغّل إمدادات المياه والصرف الصحي وإعادة الاستخدام. وتوفر بيانات تشغيلية لمحور الأمن المائي، وهي محورية في اختبار سياسات الطلب والإمداد."},{"nameEn":"General Authority for Statistics (GASTAT)","nameAr":"الهيئة العامة للإحصاء","interest":4,"influence":3,"roleEn":"Sets national statistical standards and publishes official statistics. The Office aligns its environmental statistics, classifications and release practice with it.","roleAr":"تضع المعايير الإحصائية الوطنية وتنشر الإحصاءات الرسمية. ويواءم المكتب إحصاءاته البيئية وتصنيفاته وممارسات النشر لديه معها."},{"nameEn":"Saudi Data and AI Authority (SDAIA)","nameAr":"الهيئة السعودية للبيانات والذكاء الاصطناعي","interest":3,"influence":4,"roleEn":"Sets national direction on data governance and artificial intelligence. The Office follows its guidance in data sharing, classification and responsible use of analytics.","roleAr":"تحدد التوجه الوطني لحوكمة البيانات والذكاء الاصطناعي. ويتبع المكتب إرشاداتها في مشاركة البيانات وتصنيفها والاستخدام المسؤول للتحليلات."},{"nameEn":"Universities and research centres (KAUST, KFUPM, KACST)","nameAr":"الجامعات ومراكز الأبحاث (كاوست، جامعة الملك فهد للبترول والمعادن، مدينة الملك عبدالعزيز للعلوم والتقنية)","interest":4,"influence":2,"roleEn":"Provide research, modelling expertise and independent review. They are partners for simulation models, scenario work and capability building.","roleAr":"توفر الأبحاث والخبرة في النمذجة والمراجعة المستقلة. وهي شريك في نماذج المحاكاة وأعمال السيناريوهات وبناء القدرات."},{"nameEn":"International organisations (FAO, UNEP, World Bank)","nameAr":"المنظمات الدولية (منظمة الأغذية والزراعة، برنامج الأمم المتحدة للبيئة، البنك الدولي)","interest":3,"influence":3,"roleEn":"Define global indicators and reporting frameworks and offer technical benchmarks. Engagement is through reporting, methodological exchange and joint studies.","roleAr":"تحدد المؤشرات العالمية وأطر الإبلاغ وتقدم مرجعيات فنية. ويتم التفاعل عبر الإبلاغ وتبادل المنهجيات والدراسات المشتركة."}]', 1),
('01M4D6CAY6GMQ8Y8VXTWM61D53', '01M4D6CAY5T0XKCNYRFK5B2F2D', 'challenge', '[{"titleEn":"Plans written to different standards","titleAr":"خطط مُعدّة وفق معايير متباينة","descriptionEn":"Entity and sector strategies arrive in different structures, with objectives that mix outcomes, outputs and activities in the same list. The Office then spends review time reconstructing the results chain instead of judging the substance, and the resulting plans cannot be compared or aggregated into a national picture.","descriptionAr":"تصل استراتيجيات الجهات والقطاعات بهياكل مختلفة، وبأهداف تخلط النتائج والمخرجات والأنشطة في قائمة واحدة. فيستهلك المكتب وقت المراجعة في إعادة بناء سلسلة النتائج بدل الحكم على المضمون، وتبقى الخطط الناتجة غير قابلة للمقارنة أو للتجميع في صورة وطنية واحدة.","goalCode":"G1"},{"titleEn":"Environmental data held in silos","titleAr":"بيانات بيئية محتجزة في صوامع","descriptionEn":"Much of the data the Office needs already exists inside entity systems, but access depends on personal relationships and case by case correspondence. Without standing agreements and a shared governance model, collection is repeated for data the sector already holds.","descriptionAr":"يوجد جانب كبير من البيانات التي يحتاجها المكتب داخل نظم الجهات، لكن الوصول إليها يعتمد على العلاقات الشخصية والمراسلات في كل حالة على حدة. ومن دون اتفاقيات دائمة ونموذج حوكمة مشترك يتكرر جمع بيانات يملكها القطاع أصلاً.","goalCode":"G2"},{"titleEn":"Data that arrives after the decision","titleAr":"بيانات تصل بعد اتخاذ القرار","descriptionEn":"Environmental data is often released weeks or months after the period it describes, and revisions are not always explained. Decision makers turn to faster but less reliable sources, and the Office''s figures lose influence at the moment they matter most.","descriptionAr":"تُنشر البيانات البيئية في الغالب بعد أسابيع أو أشهر من الفترة التي تصفها، ولا تُشرح المراجعات دائماً. فيلجأ صناع القرار إلى مصادر أسرع وأقل موثوقية، وتفقد أرقام المكتب أثرها في اللحظة التي تكون فيها الأهم.","goalCode":"G2"},{"titleEn":"Foresight that is read but not used","titleAr":"استشراف يُقرأ ولا يُستخدم","descriptionEn":"Scans, scenarios and risk notes are produced but rarely tied to a decision on the calendar. Without a route into planning cycles and committee agendas, early signals about water, climate or land remain interesting reading rather than prompts for action.","descriptionAr":"تُنتج المسوح والسيناريوهات ومذكرات المخاطر لكنها نادراً ما ترتبط بقرار مدرج في الروزنامة. ومن دون مسار إلى دورات التخطيط وجداول أعمال اللجان، تبقى الإشارات المبكرة عن المياه والمناخ والأراضي مادة للقراءة لا دافعاً للعمل.","goalCode":"G3"},{"titleEn":"Regulation and internal work carried by spreadsheets","titleAr":"التنظيمات والعمل الداخلي محمولان على الجداول الإلكترونية","descriptionEn":"Regulatory changes, approvals, reporting and internal performance figures are tracked in spreadsheets and email threads. Context is lost when people change roles, and nobody can see at a glance which regulation affects which plan or indicator.","descriptionAr":"تُتابَع التغييرات التنظيمية والموافقات والتقارير وأرقام الأداء الداخلي في جداول إلكترونية وسلاسل بريد. ويضيع السياق عند تغيير الأدوار، ولا يستطيع أحد أن يرى بنظرة واحدة أي تنظيم يؤثر في أي خطة أو مؤشر.","goalCode":"G4"},{"titleEn":"A sector story told in fragments","titleAr":"رواية قطاعية مجزأة","descriptionEn":"Entities, the Office and international bodies each tell part of the environmental story with different figures and different timing. Without one coordinated voice and an agreed set of headline messages, public and partner understanding stays partial.","descriptionAr":"تروي الجهات والمكتب والهيئات الدولية كل منها جزءاً من القصة البيئية بأرقام وتوقيتات مختلفة. ومن دون صوت منسّق واحد ورسائل رئيسية متفق عليها يظل فهم الجمهور والشركاء جزئياً.","goalCode":"G5"}]', 2),
('01M4D6CAY6F3C5E3GZB0W07EA9', '01M4D6CAY5T0XKCNYRFK5B2F2D', 'baseline', '[{"textEn":"Illustrative baseline: in 2024, about 60 percent of entities submitted their annual implementation plans by the published deadline, and a number of entities submitted after the national report had been drafted.","textAr":"خط أساس توضيحي: في عام 2024 رفعت نحو 60 بالمئة من الجهات خططها التنفيذية السنوية في الموعد المعلن، فيما رفعت جهات أخرى خططها بعد إعداد مسودة التقرير الوطني."},{"textEn":"Illustrative baseline: in 2024, around 70 percent of scheduled data releases were published on the date announced in the advance release calendar.","textAr":"خط أساس توضيحي: في عام 2024 نُشر نحو 70 بالمئة من إصدارات البيانات المجدولة في التاريخ المعلن في روزنامة النشر المسبقة."},{"textEn":"Illustrative baseline: the average gap between the end of the reference period and publication for quarterly environmental indicators was about 90 days in 2024, against a good practice target the Office has set at 60 days.","textAr":"خط أساس توضيحي: بلغ متوسط الفجوة بين نهاية الفترة المرجعية والنشر للمؤشرات البيئية الربعية نحو 90 يوماً في عام 2024، مقابل مستهدف الممارسة الجيدة الذي وضعه المكتب عند 60 يوماً."},{"textEn":"Illustrative baseline: at the end of 2024, fewer than half of the priority administrative data sources identified by the Office were covered by a signed data sharing agreement.","textAr":"خط أساس توضيحي: في نهاية عام 2024 كان أقل من نصف مصادر البيانات الإدارية ذات الأولوية التي حددها المكتب مغطى باتفاقية مشاركة بيانات موقّعة."},{"textEn":"Illustrative baseline: NES monitoring covered a few hundred initiatives in 2024, of which roughly one third submitted a complete evidence pack with their progress report.","textAr":"خط أساس توضيحي: غطّت متابعة الاستراتيجية الوطنية للبيئة بضع مئات من المبادرات في عام 2024، قدّم نحو ثلثها حزمة أدلة مكتملة مع تقرير التقدم."},{"textEn":"Illustrative baseline: staff turnover at the Office was in the low teens in percentage terms in 2024 and higher in specialist data and modelling roles, with filling a specialist vacancy taking about six months on average.","textAr":"خط أساس توضيحي: بلغ دوران الموظفين في المكتب نسبة تقارب العشرة بالمئة وما فوقها قليلاً في عام 2024، وارتفع في أدوار البيانات والنمذجة المتخصصة، مع استغراق شغل الشاغر المتخصص نحو ستة أشهر في المتوسط."},{"textEn":"Illustrative baseline: by mid 2025, only a small minority of the planning staff working in entities had completed certified training in results based planning.","textAr":"خط أساس توضيحي: بحلول منتصف عام 2025 لم يكن قد أتمّ التدريب المعتمد على التخطيط القائم على النتائج سوى أقلية صغيرة من العاملين في التخطيط داخل الجهات."},{"textEn":"Illustrative baseline: the open data portal held a few hundred published datasets at the end of 2024, and less than half of user support requests were answered within five working days.","textAr":"خط أساس توضيحي: ضمّت بوابة البيانات المفتوحة بضع مئات من مجموعات البيانات المنشورة في نهاية عام 2024، وأُجيب عن أقل من نصف طلبات دعم المستخدمين خلال خمسة أيام عمل."},{"textEn":"Illustrative baseline: at the start of 2025 the Office operated a small number of policy simulation models and delivered two strategic risk briefings to leadership during 2024.","textAr":"خط أساس توضيحي: في بداية عام 2025 كان المكتب يشغّل عدداً محدوداً من نماذج محاكاة السياسات، وقدّم إحاطتين استراتيجيتين عن المخاطر إلى القيادة خلال عام 2024."},{"textEn":"Illustrative baseline: at the start of 2025 only a handful of the Office''s core internal processes were automated end to end, and most internal performance reporting was still compiled manually in spreadsheets.","textAr":"خط أساس توضيحي: في بداية عام 2025 لم يكن مؤتمتاً من البداية إلى النهاية سوى عدد قليل من العمليات الداخلية الأساسية للمكتب، وظل معظم تقارير الأداء الداخلي يُعدّ يدوياً في جداول إلكترونية."}]', 3);
