INSERT INTO "council_governance" ("id", "strategy_id", "body_name_en", "body_name_ar", "role_en", "role_ar", "cadence", "members_json", "sort") VALUES
('01M4D6CBDGB3HWFM9T0MHZ86KP', '01M4D6CAY5T0XKCNYRFK5B2F2D', 'Strategy Steering Committee', 'لجنة توجيه الاستراتيجية', 'Chaired by the Programme Director, the committee owns the institutional strategy: it approves the annual targets, reviews the scorecard and the risk register each quarter, decides on the reallocation of budget and people between projects, and escalates blockers that departments cannot resolve on their own.', 'برئاسة مدير البرنامج، تتولى اللجنة ملكية الاستراتيجية المؤسسية: تعتمد المستهدفات السنوية، وتستعرض بطاقة الأداء وسجل المخاطر كل ربع سنة، وتبت في إعادة توزيع الموازنة والكوادر بين المشاريع، وتعالج المعوقات التي تعجز الإدارات عن حلها بمفردها.', 'quarterly', '[{"en":"Programme Director, Chair","ar":"مدير البرنامج، رئيساً"},{"en":"Head of the Strategy and Performance Sector","ar":"رئيس قطاع الاستراتيجية والأداء"},{"en":"Head of the Data and Knowledge Sector","ar":"رئيس قطاع البيانات والمعرفة"},{"en":"Head of the Regulatory Affairs Sector","ar":"رئيس قطاع الشؤون التنظيمية"},{"en":"Head of the Corporate Services Sector","ar":"رئيس قطاع الخدمات المؤسسية"},{"en":"Director of Strategy Development, Rapporteur","ar":"مدير إدارة تطوير الاستراتيجية، مقرراً"}]', 0),
('01M4D6CBDG08FTH89GSPJBA2YY', '01M4D6CAY5T0XKCNYRFK5B2F2D', 'Strategy Office', 'مكتب الاستراتيجية', 'The Strategy Development department acts as the Strategy Office. It maintains the results chain and the indicator cards, collects actuals on each indicator''s cadence, challenges the quality of the evidence behind a reported figure, prepares the quarterly pack for the steering committee, and keeps the change log of every amendment to the strategy.', 'تقوم إدارة تطوير الاستراتيجية بدور مكتب الاستراتيجية. فتتعهد سلسلة النتائج وبطاقات المؤشرات، وتجمع القيم الفعلية وفق دورية كل مؤشر، وتراجع جودة الأدلة وراء أي رقم مرفوع، وتُعدّ الحزمة الربعية للجنة التوجيهية، وتحتفظ بسجل التغييرات لكل تعديل على الاستراتيجية.', 'monthly', '[{"en":"Director of Strategy Development, Head of the Strategy Office","ar":"مدير إدارة تطوير الاستراتيجية، رئيساً لمكتب الاستراتيجية"},{"en":"Strategy and institutional performance analysts","ar":"محللو الاستراتيجية والأداء المؤسسي"},{"en":"Representative of Planning Quality and Standards","ar":"ممثل إدارة جودة الخطط والمعايير"},{"en":"Representative of Programme Monitoring","ar":"ممثل إدارة متابعة البرنامج"},{"en":"Representative of Finance and Administration for the budget link","ar":"ممثل إدارة المالية والشؤون الإدارية للربط مع الموازنة"}]', 1),
('01M4D6CBDGDZWM4KZ7WZ2VY7V7', '01M4D6CAY5T0XKCNYRFK5B2F2D', 'Department Focal Points Network', 'شبكة ضباط الاتصال في الإدارات', 'One named focal point in every department carries the strategy inside the department: updating project and activity status, entering actuals against indicators the department owns, and raising risks and dependencies early. The network meets monthly and is the Strategy Office''s working channel into the departments.', 'يتولى ضابط اتصال مسمّى في كل إدارة حمل الاستراتيجية داخل إدارته: تحديث حالة المشاريع والأنشطة، وإدخال القيم الفعلية للمؤشرات التي تملكها الإدارة، ورفع المخاطر والاعتماديات مبكراً. وتجتمع الشبكة شهرياً وهي قناة عمل مكتب الاستراتيجية مع الإدارات.', 'monthly', '[{"en":"Focal points of the departments of the Strategy and Performance Sector","ar":"ضباط الاتصال في إدارات قطاع الاستراتيجية والأداء"},{"en":"Focal points of the departments of the Data and Knowledge Sector","ar":"ضباط الاتصال في إدارات قطاع البيانات والمعرفة"},{"en":"Focal points of the departments of the Regulatory Affairs Sector","ar":"ضباط الاتصال في إدارات قطاع الشؤون التنظيمية"},{"en":"Focal points of the theme departments for water, agriculture, climate, land, waste and air","ar":"ضباط الاتصال في إدارات المحاور للمياه والزراعة والمناخ والأراضي والنفايات والهواء"},{"en":"Focal points of the departments of the Corporate Services Sector","ar":"ضباط الاتصال في إدارات قطاع الخدمات المؤسسية"},{"en":"Focal points of the Office of the Programme Director departments","ar":"ضباط الاتصال في إدارات مكتب مدير البرنامج"}]', 2);
