INSERT INTO "council_indicators" ("id", "node_id", "code", "name_en", "name_ar", "definition_en", "definition_ar", "formula_en", "formula_ar", "unit", "direction", "baseline_year", "baseline_value", "frequency", "data_source_en", "data_source_ar", "means_of_verification_en", "means_of_verification_ar", "responsible_user_id", "linked_statistics_indicator_id", "notes_en", "notes_ar", "sort", "created_at", "updated_at") VALUES
('01M4D6CB0H25CHHHYTMVGKHC5C', '01M4D6CAY625SEB1WV3KN64N2M', 'CI-001', 'Entity environment strategies conforming to the national results framework standard', 'نسبة استراتيجيات الجهات البيئية المطابقة لمعيار إطار النتائج الوطني', 'Counts entities whose current environment, water or agriculture strategy was assessed as fully conforming to the national results framework standard, as a share of all entities expected to hold one.', 'يحصي الجهات التي قيمت استراتيجيتها السارية في البيئة أو المياه أو الزراعة على أنها مطابقة تماما لمعيار إطار النتائج الوطني، منسوبة إلى جميع الجهات المتوقع أن تملك استراتيجية.', 'Number of entities assessed as fully conforming divided by the number of entities expected to hold a strategy, times 100.', 'عدد الجهات المقيمة على أنها مطابقة تماما مقسوما على عدد الجهات المتوقع أن تملك استراتيجية، مضروبا في 100.', 'percent', 'up_good', '2024', 38.0, 'yearly', 'Strategy review gateway records held by Planning Quality and Standards.', 'سجلات بوابة مراجعة الاستراتيجيات لدى إدارة جودة الخطط والمعايير.', 'Signed review reports and the annual conformity register published with the NES progress report.', 'تقارير المراجعة الموقعة وسجل المطابقة السنوي المنشور مع تقرير تقدم الاستراتيجية الوطنية للبيئة.', '01M4D6BHET7Q90XBQ6PJ0SVCCM', NULL, 'An entity counts only once even if it holds more than one sector strategy. Illustrative baseline and target.', 'تحتسب الجهة مرة واحدة فقط حتى لو كانت تملك أكثر من استراتيجية قطاعية. خط الأساس والمستهدف توضيحيان.', 0, '2026-10-08T07:24:26.001Z', '2026-10-08T07:24:26.001Z'),
('01M4D6CB0J235MJVVV0C47345A', '01M4D6CAY625SEB1WV3KN64N2M', 'CI-002', 'NES initiative delivery rate against the annual plan', 'معدل تنفيذ مبادرات الاستراتيجية الوطنية للبيئة مقارنة بالخطة السنوية', 'Measures how much of the planned annual delivery of National Environment Strategy initiatives was achieved, weighted by each initiative''s planned milestones for the year.', 'يقيس ما تحقق من التنفيذ السنوي المخطط لمبادرات الاستراتيجية الوطنية للبيئة، مرجحا بمحطات كل مبادرة المقررة للسنة.', 'Sum of milestones completed in the year divided by the sum of milestones planned for the year, times 100.', 'مجموع المحطات المنجزة خلال السنة مقسوما على مجموع المحطات المخططة للسنة، مضروبا في 100.', 'percent', 'up_good', '2024', 61.0, 'yearly', 'NES monitoring system returns submitted by implementing entities such as MEWA and its national centres.', 'بيانات نظام متابعة الاستراتيجية الوطنية للبيئة المقدمة من الجهات المنفذة مثل وزارة البيئة والمياه والزراعة ومراكزها الوطنية.', 'Annual NES progress report and the verification sample audited by Programme Monitoring.', 'التقرير السنوي لتقدم الاستراتيجية وعينة التحقق التي تدققها إدارة متابعة البرنامج.', '01M4D6BHET7Q90XBQ6PJ0SVCCM', NULL, 'Milestones cancelled by a formal Programme Steering Committee decision are removed from both numerator and denominator.', 'تستبعد المحطات الملغاة بقرار رسمي من اللجنة التوجيهية للبرنامج من البسط والمقام معا.', 1, '2026-10-08T07:24:26.002Z', '2026-10-08T07:24:26.002Z'),
('01M4D6CB0K96BE1EP2CSCKEP2N', '01M4D6CAY6R3SYHXXXG7N8R26H', 'CI-003', 'Compliance of environmental statistics with international quality standards', 'امتثال الإحصاءات البيئية للمعايير الدولية للجودة', 'Counts assessed environmental data domains (water, agriculture, climate, biodiversity, waste, air) that meet all mandatory criteria of the data quality framework, as a share of all assessed domains.', 'يحصي مجالات البيانات البيئية المقيمة (المياه والزراعة والمناخ والتنوع الأحيائي والنفايات والهواء) التي تستوفي جميع المعايير الإلزامية في إطار جودة البيانات، منسوبة إلى جميع المجالات المقيمة.', 'Number of domains meeting all mandatory criteria divided by the number of domains assessed, times 100.', 'عدد المجالات المستوفية لجميع المعايير الإلزامية مقسوما على عدد المجالات المقيمة، مضروبا في 100.', 'percent', 'up_good', '2024', 72.0, 'yearly', 'Quality assessment register of Data Quality and Standards, with reference to GASTAT quality practice.', 'سجل تقييم الجودة لدى إدارة جودة البيانات والمعايير، مع الرجوع إلى ممارسات الجودة لدى الهيئة العامة للإحصاء.', 'Domain assessment reports plus the periodic external peer review.', 'تقارير تقييم المجالات إضافة إلى المراجعة النظيرة الخارجية الدورية.', '01M4D6BHEQ32QCSD0FWQPS6A3W', NULL, 'Domains are reassessed on a three year rolling cycle, so the yearly figure covers the latest assessment on record.', 'تعاد تقييم المجالات وفق دورة متجددة مدتها ثلاث سنوات، لذا يغطي الرقم السنوي أحدث تقييم مسجل.', 2, '2026-10-08T07:24:26.003Z', '2026-10-08T07:24:26.003Z'),
('01M4D6CB0MFPD4MJXZ8TN9JV4D', '01M4D6CAY6R3SYHXXXG7N8R26H', 'CI-004', 'Stakeholder trust in environmental data', 'ثقة أصحاب المصلحة في البيانات البيئية', 'Average rating given by respondents to the annual users survey when asked how far they trust the environmental data published by the Office.', 'متوسط التقييم الذي يمنحه المستجيبون في مسح المستخدمين السنوي عند سؤالهم عن مدى ثقتهم في البيانات البيئية التي ينشرها المكتب.', 'Sum of trust ratings on a ten point scale divided by the number of valid responses.', 'مجموع تقييمات الثقة على مقياس من عشر درجات مقسوما على عدد الاستجابات الصحيحة.', 'score', 'up_good', '2024', 6.8, 'yearly', 'Annual users survey run by the Communications and Data Affairs teams.', 'مسح المستخدمين السنوي الذي تنفذه إدارتا الاتصال وشؤون البيانات البيئية.', 'Survey instrument, response file and the published methodology note.', 'أداة المسح وملف الاستجابات ومذكرة المنهجية المنشورة.', '01M4D6BHEQ32QCSD0FWQPS6A3W', NULL, 'Respondents include entities, researchers, media and the public. Illustrative scale.', 'يشمل المستجيبون الجهات والباحثين والإعلام والجمهور. المقياس توضيحي.', 3, '2026-10-08T07:24:26.004Z', '2026-10-08T07:24:26.004Z'),
