INSERT INTO "council_nodes" ("id", "strategy_id", "parent_id", "level", "code", "title_en", "title_ar", "description_en", "description_ar", "owner_unit_id", "owner_user_id", "status", "start_date", "end_date", "budget_qar", "inputs_json", "priority_impact", "priority_feasibility", "sort", "source_ref", "is_illustrative", "created_at", "updated_at") VALUES
('01M4D6CAY625SEB1WV3KN64N2M', '01M4D6CAY5T0XKCNYRFK5B2F2D', NULL, 'goal', 'G1', 'Excellence in environmental strategy and delivery', 'التميز في الاستراتيجية البيئية وتنفيذها', 'The Office makes environmental planning a disciplined craft: one results based method, one set of templates, and a technical review that every sector and entity strategy passes before it is adopted. It supports the delivery of the National Environment Strategy with evidence and hands on implementation help rather than correspondence, and it tests major policies through simulation and trials before they are committed. The goal is achieved when plans across the sector are comparable, monitorable and actually delivered.', 'يجعل المكتب التخطيط البيئي ممارسة منضبطة تقوم على منهجية موحدة قائمة على النتائج، ونماذج معتمدة، ومراجعة فنية تمر بها كل استراتيجية قطاعية ومؤسسية قبل اعتمادها. ويدعم تنفيذ الاستراتيجية الوطنية للبيئة بالأدلة وبالدعم الميداني المباشر لا بالمراسلات، ويختبر السياسات الكبرى عبر المحاكاة والتجارب قبل الالتزام بها. ويتحقق الهدف حين تصبح خطط القطاع قابلة للمقارنة والمتابعة والإنجاز الفعلي.', '01M4D6BGEM8CD2PD6VB691TCQP', NULL, 'on_track', '2025-01-01', '2030-12-31', NULL, NULL, NULL, NULL, 0, 'EnviroAI Programme Strategy, illustrative data', 1, '2026-10-08T07:24:25.926Z', '2026-10-08T07:24:25.926Z'),
('01M4D6CAY6R3SYHXXXG7N8R26H', '01M4D6CAY5T0XKCNYRFK5B2F2D', NULL, 'goal', 'G2', 'Trusted environmental data and statistics', 'بيانات وإحصاءات بيئية موثوقة', 'The Office builds the environmental evidence base the sector relies on: data that meets international quality standards, is governed and shared as an asset across entities, and is easy for users to find, trust and reuse. It modernises how monitoring data is captured and produced, publishes on a predictable calendar and explains every revision. The goal is achieved when decision makers reach for the Office''s figures first.', 'يبني المكتب قاعدة الأدلة البيئية التي يعتمد عليها القطاع: بيانات تستوفي المعايير الدولية للجودة، وتُحوكَم وتُشارَك بين الجهات بوصفها أصلاً، ويسهل على المستخدمين إيجادها والوثوق بها وإعادة استخدامها. ويحدّث طريقة التقاط بيانات الرصد وإنتاجها، وينشر وفق روزنامة متوقعة ويشرح كل مراجعة. ويتحقق الهدف حين يلجأ صناع القرار إلى أرقام المكتب أولاً.', '01M4D6BGEHC8RJHJPQ0481V7JY', NULL, 'on_track', '2025-01-01', '2030-12-31', NULL, NULL, NULL, NULL, 1, 'EnviroAI Programme Strategy, illustrative data', 1, '2026-10-08T07:24:25.926Z', '2026-10-08T07:24:25.926Z'),
('01M4D6CAY743SM5Q85A348YH1Q', '01M4D6CAY5T0XKCNYRFK5B2F2D', NULL, 'goal', 'G3', 'Foresight and readiness for environmental risk', 'الاستشراف والجاهزية للمخاطر البيئية', 'The Office scans for emerging risks and opportunities, briefs leadership every quarter and builds scenarios for Saudi Vision 2030 environmental targets and beyond. It tests how people respond to water and waste policies through behavioural trials, and grows a foresight network across entities. The goal is achieved when long term choices on water, climate and land visibly change because of what foresight showed.', 'يرصد المكتب المخاطر والفرص الناشئة، ويُطلع القيادة كل ربع سنة، ويبني سيناريوهات لمستهدفات رؤية السعودية 2030 البيئية وما بعدها. ويختبر استجابة الناس لسياسات المياه والنفايات عبر التجارب السلوكية، وينمّي شبكة استشراف عبر الجهات. ويتحقق الهدف حين تتغير الخيارات الطويلة الأجل في المياه والمناخ والأراضي بشكل ملموس بفضل ما أظهره الاستشراف.', '01M4D6BGENG69HJJCBAM584JAY', NULL, 'on_track', '2025-01-01', '2030-12-31', NULL, NULL, NULL, NULL, 2, 'EnviroAI Programme Strategy, illustrative data', 1, '2026-10-08T07:24:25.927Z', '2026-10-08T07:24:25.927Z'),
('01M4D6CAY7TCCG4N0FGRMJ7VEW', '01M4D6CAY5T0XKCNYRFK5B2F2D', NULL, 'goal', 'G4', 'Regulatory clarity and institutional excellence', 'الوضوح التنظيمي والتميز المؤسسي', 'The Office keeps regulation and institutional knowledge current and findable, and runs its own work on modern digital platforms. A regulatory register tracks changes and their effect on plans and indicators, knowledge is captured so a change of role never removes context, and information security and continuity are built in. The goal is achieved when anyone in the Office can find the current rule, its source and its impact in minutes.', 'يُبقي المكتب الأنظمة والمعرفة المؤسسية محدّثة وسهلة الاسترجاع، ويدير عمله على منصات رقمية حديثة. يتتبع سجل تنظيمي التغييرات وأثرها على الخطط والمؤشرات، وتُوثَّق المعرفة فلا يزيل تغيير الدور سياقاً، وتُبنى أمن المعلومات والاستمرارية في صلب العمل. ويتحقق الهدف حين يستطيع أي موظف في المكتب إيجاد النظام الحالي ومصدره وأثره خلال دقائق.', '01M4D6CAH3BF25TQ3FKMJQRKF3', NULL, 'on_track', '2025-01-01', '2030-12-31', NULL, NULL, NULL, NULL, 3, 'EnviroAI Programme Strategy, illustrative data', 1, '2026-10-08T07:24:25.927Z', '2026-10-08T07:24:25.927Z'),
('01M4D6CAY7TXWV9CV7FGPGC1QJ', '01M4D6CAY5T0XKCNYRFK5B2F2D', NULL, 'goal', 'G5', 'Partnerships and communication', 'الشراكات والاتصال', 'The Office extends its reach through structured partnerships with entities, universities and international organisations, and tells the environmental story with one clear voice. It engages the global indicator frameworks the Kingdom reports against, publishes on a coordinated plan and runs steering committee sessions that end in decisions with owners. The goal is achieved when partners and the public understand the national picture and what is being done about it.', 'يوسّع المكتب أثره عبر شراكات منظمة مع الجهات والجامعات والمنظمات الدولية، ويروي القصة البيئية بصوت واحد واضح. ويتفاعل مع أطر المؤشرات العالمية التي تُبلّغ المملكة عنها، وينشر وفق خطة منسقة، ويدير جلسات اللجنة التوجيهية بحيث تنتهي بقرارات لها مسؤولون. ويتحقق الهدف حين يفهم الشركاء والجمهور الصورة الوطنية وما يُعمل بشأنها.', '01M4D6CAH5RK2PHTPB3RX644SG', NULL, 'on_track', '2025-01-01', '2030-12-31', NULL, NULL, NULL, NULL, 4, 'EnviroAI Programme Strategy, illustrative data', 1, '2026-10-08T07:24:25.927Z', '2026-10-08T07:24:25.927Z'),
('01M4D6CAY712J87RZBWHJSWQDZ', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAY625SEB1WV3KN64N2M', 'intermediate_outcome', 'G1.IO1', 'Environment strategies and plans follow one national standard', 'اتباع استراتيجيات البيئة وخططها معياراً وطنياً موحداً', 'Every sector and entity strategy follows the same results chain, uses the same templates and carries indicator cards that meet a published quality checklist. Planning teams across the sector are trained and certified in the method, so compliance comes from capability rather than from correction.', 'تتبع كل استراتيجية قطاعية ومؤسسية سلسلة النتائج ذاتها وتستخدم النماذج ذاتها وتتضمن بطاقات مؤشرات مستوفية لقائمة تحقق معلنة للجودة. وتُدرَّب فرق التخطيط في القطاع وتُعتمد في المنهجية، فيأتي الالتزام من القدرة لا من التصحيح اللاحق.', '01M4D6CAGYP0HZ6XYMWHB2BYZT', NULL, 'on_track', '2025-01-01', '2030-12-31', NULL, NULL, NULL, NULL, 5, 'EnviroAI Programme Strategy, illustrative data', 1, '2026-10-08T07:24:25.927Z', '2026-10-08T07:24:25.927Z'),
('01M4D6CAY8X9J4QD2PVHVKD2ZE', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAY625SEB1WV3KN64N2M', 'intermediate_outcome', 'G1.IO2', 'NES delivery is monitored and supported with evidence', 'متابعة تنفيذ الاستراتيجية الوطنية للبيئة ودعمه بالأدلة', 'Progress on National Environment Strategy initiatives is reported on a fixed cycle against verifiable evidence, and lagging initiatives receive hands on support. Leadership sees one integrated picture of delivery and can act on it before delays become failures.', 'يُبلَّغ عن التقدم في مبادرات الاستراتيجية الوطنية للبيئة وفق دورة ثابتة وبأدلة يمكن التحقق منها، وتتلقى المبادرات المتأخرة دعماً مباشراً. وترى القيادة صورة واحدة متكاملة للإنجاز وتستطيع التصرف قبل أن يتحول التأخر إلى إخفاق.', '01M4D6BGEN0X0HZVKB2P6E6678', NULL, 'on_track', '2025-01-01', '2030-12-31', NULL, NULL, NULL, NULL, 6, 'EnviroAI Programme Strategy, illustrative data', 1, '2026-10-08T07:24:25.928Z', '2026-10-08T07:24:25.928Z'),
('01M4D6CAY83G3SK14HDM5N066W', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAY625SEB1WV3KN64N2M', 'intermediate_outcome', 'G1.IO3', 'Policies and regulations are tested before they are adopted', 'اختبار السياسات والأنظمة قبل اعتمادها', 'Major policy proposals on water, agriculture and climate pass through simulation or a controlled trial before they reach the decision table. Decision makers see likely effects, costs and trade-offs in advance, and weak proposals are improved or dropped early.', 'تمر مقترحات السياسات الكبرى في المياه والزراعة والمناخ عبر المحاكاة أو تجربة مضبوطة قبل وصولها إلى طاولة القرار. ويرى صناع القرار الآثار المرجحة والتكاليف والمفاضلات مسبقاً، وتُحسَّن المقترحات الضعيفة أو تُسقَط مبكراً.', '01M4D6CAH2M4YTAQ9BTVWE0B89', NULL, 'on_track', '2025-01-01', '2030-12-31', NULL, NULL, NULL, NULL, 7, 'EnviroAI Programme Strategy, illustrative data', 1, '2026-10-08T07:24:25.928Z', '2026-10-08T07:24:25.928Z'),
('01M4D6CAY8EQ6JVSKMY8W56F99', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAY6R3SYHXXXG7N8R26H', 'intermediate_outcome', 'G2.IO1', 'Environmental data meets international quality standards', 'استيفاء البيانات البيئية للمعايير الدولية للجودة', 'Environmental data is produced under a documented quality framework, on modern monitoring and production systems, with accredited metadata and classifications. Quality is assessed against international practice and the results are published.', 'تُنتج البيانات البيئية في إطار جودة موثق، وعلى نظم رصد وإنتاج حديثة، مع بيانات وصفية وتصنيفات معتمدة. وتُقيَّم الجودة قياساً إلى الممارسات الدولية وتُنشر النتائج.', '01M4D6CAH4W5AVSABK3GFKSWC9', NULL, 'on_track', '2025-01-01', '2030-12-31', NULL, NULL, NULL, NULL, 8, 'EnviroAI Programme Strategy, illustrative data', 1, '2026-10-08T07:24:25.928Z', '2026-10-08T07:24:25.928Z'),
('01M4D6CAY8N3V3RD5SWNQVY6E5', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAY6R3SYHXXXG7N8R26H', 'intermediate_outcome', 'G2.IO2', 'Environmental data is shared and governed as an asset', 'مشاركة البيانات البيئية وحوكمتها بوصفها أصلاً', 'Standing agreements, clear ownership and one catalogue let entities share the data they hold with confidence. Priority administrative sources flow to the Office on agreed terms, and users can see what exists, who owns it and under what conditions it can be used.', 'تتيح الاتفاقيات الدائمة والملكية الواضحة وفهرس واحد للجهات مشاركة ما تحتفظ به من بيانات بثقة. وتصل مصادر البيانات الإدارية ذات الأولوية إلى المكتب وفق شروط متفق عليها، ويرى المستخدمون ما هو موجود ومن يملكه وبأي شروط يمكن استخدامه.', '01M4D6CAH5B7NG3WSDB4KQWVYD', NULL, 'on_track', '2025-01-01', '2030-12-31', NULL, NULL, NULL, NULL, 9, 'EnviroAI Programme Strategy, illustrative data', 1, '2026-10-08T07:24:25.928Z', '2026-10-08T07:24:25.928Z'),
('01M4D6CAY9CRAK625681WJ2DSV', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAY6R3SYHXXXG7N8R26H', 'intermediate_outcome', 'G2.IO3', 'Users find, trust and reuse Office data', 'إيجاد المستخدمين لبيانات المكتب والوثوق بها وإعادة استخدامها', 'Open data and dissemination services are easy to use, releases follow a published calendar, and revisions are explained. Users are supported to understand and apply the data, and reuse by entities, researchers and the public grows year on year.', 'تتسم خدمات البيانات المفتوحة والنشر بسهولة الاستخدام، وتتبع الإصدارات روزنامة معلنة، وتُشرح المراجعات. ويُدعم المستخدمون لفهم البيانات وتطبيقها، وينمو استخدامها من الجهات والباحثين والجمهور عاماً بعد عام.', '01M4D6BGEJJ8DT77CSYCK82ZBV', NULL, 'on_track', '2025-01-01', '2030-12-31', NULL, NULL, NULL, NULL, 10, 'EnviroAI Programme Strategy, illustrative data', 1, '2026-10-08T07:24:25.929Z', '2026-10-08T07:24:25.929Z'),
('01M4D6CAY9S6Q97NS5F7VGN1E9', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAY743SM5Q85A348YH1Q', 'intermediate_outcome', 'G3.IO1', 'Emerging risks and opportunities are detected early', 'رصد المخاطر والفرص الناشئة مبكراً', 'A standing scanning system tracks signals across water, agriculture, climate, land, waste and air, and leadership receives a short strategic risk briefing every quarter with proposed responses and owners.', 'يتتبع نظام مسح دائم الإشارات في المياه والزراعة والمناخ والأراضي والنفايات والهواء، وتتلقى القيادة إحاطة موجزة عن المخاطر الاستراتيجية كل ربع سنة مع الاستجابات المقترحة والمسؤولين.', '01M4D6CAH2Z16QWD7SDJF5XMQ9', NULL, 'on_track', '2025-01-01', '2030-12-31', NULL, NULL, NULL, NULL, 11, 'EnviroAI Programme Strategy, illustrative data', 1, '2026-10-08T07:24:25.929Z', '2026-10-08T07:24:25.929Z'),
('01M4D6CAY92YQBH1AESJ6YQT59', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAY743SM5Q85A348YH1Q', 'intermediate_outcome', 'G3.IO2', 'Long term environmental choices are informed by foresight', 'استنارة الخيارات البيئية الطويلة الأجل بالاستشراف', 'Scenario sets, behavioural insight and a network of foresight practitioners across entities feed into planning cycles and policy choices, so that long term options are weighed before they are closed off.', 'تغذي مجموعات السيناريوهات والرؤى السلوكية وشبكة ممارسي الاستشراف في الجهات دورات التخطيط والخيارات السياساتية، فتُوزن الخيارات الطويلة الأجل قبل أن تُغلق.', '01M4D6BGENG69HJJCBAM584JAY', NULL, 'on_track', '2025-01-01', '2030-12-31', NULL, NULL, NULL, NULL, 12, 'EnviroAI Programme Strategy, illustrative data', 1, '2026-10-08T07:24:25.929Z', '2026-10-08T07:24:25.929Z'),
('01M4D6CAY9BVMRRV50KM0E4RFN', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAY7TCCG4N0FGRMJ7VEW', 'intermediate_outcome', 'G4.IO1', 'Regulation and institutional knowledge are kept current and findable', 'إبقاء الأنظمة والمعرفة المؤسسية محدّثة وسهلة الاسترجاع', 'A regulatory register records each rule in force, its source and its changes, and links it to the plans and indicators it affects. Knowledge from projects, studies and departing colleagues is captured and findable, so the Office does not relearn what it already knew.', 'يسجّل سجل تنظيمي كل نظام ساري ومصدره وتعديلاته، ويربطه بالخطط والمؤشرات التي يؤثر فيها. وتُحفظ المعرفة المستمدة من المشاريع والدراسات والزملاء المغادرين وتُتاح للاسترجاع، فلا يعيد المكتب تعلّم ما كان يعرفه.', '01M4D6CAH3BF25TQ3FKMJQRKF3', NULL, 'on_track', '2025-01-01', '2030-12-31', NULL, NULL, NULL, NULL, 13, 'EnviroAI Programme Strategy, illustrative data', 1, '2026-10-08T07:24:25.929Z', '2026-10-08T07:24:25.929Z'),
('01M4D6CAYAJRTBHMNYTHC7BQHY', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAY7TCCG4N0FGRMJ7VEW', 'intermediate_outcome', 'G4.IO2', 'Digital platforms carry the Office''s core work', 'حمل المنصات الرقمية لأعمال المكتب الأساسية', 'Core processes run on a unified digital workplace with automation where it pays back, information security and business continuity are tested, and internal performance reporting is produced from data rather than compiled by hand.', 'تُدار العمليات الأساسية على بيئة عمل رقمية موحدة مع أتمتة حيث يكون العائد مجدياً، وتُختبر أمن المعلومات واستمرارية الأعمال، وتُنتج تقارير الأداء الداخلي من البيانات بدل جمعها يدوياً.', '01M4D6BGENB6WPFZF0BJRG1PX3', NULL, 'on_track', '2025-01-01', '2030-12-31', NULL, NULL, NULL, NULL, 14, 'EnviroAI Programme Strategy, illustrative data', 1, '2026-10-08T07:24:25.930Z', '2026-10-08T07:24:25.930Z'),
('01M4D6CAYAJ2VJPSNJX0ZD89TJ', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAY7TXWV9CV7FGPGC1QJ', 'intermediate_outcome', 'G5.IO1', 'Partnerships extend the Office''s reach', 'توسيع الشراكات لنطاق عمل المكتب', 'A structured programme with entities, universities and international organisations brings in research, methods and benchmarks the Office could not build alone, and keeps national reporting against global indicators timely and consistent.', 'يجلب برنامج منظم مع الجهات والجامعات والمنظمات الدولية الأبحاث والمنهجيات والمرجعيات التي لا يستطيع المكتب بناءها بمفرده، ويحافظ على انتظام الإبلاغ الوطني مقابل المؤشرات العالمية واتساقه.', '01M4D6CAH5RK2PHTPB3RX644SG', NULL, 'on_track', '2025-01-01', '2030-12-31', NULL, NULL, NULL, NULL, 15, 'EnviroAI Programme Strategy, illustrative data', 1, '2026-10-08T07:24:25.930Z', '2026-10-08T07:24:25.930Z'),
('01M4D6CAYANDKJQDE6F63RGSPK', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAY7TXWV9CV7FGPGC1QJ', 'intermediate_outcome', 'G5.IO2', 'The Office communicates clearly with the public', 'تواصل المكتب بوضوح مع الجمهور', 'One integrated communication and publication plan sets the headline messages and the calendar, and steering committee sessions are run so that every decision is recorded, owned and followed up.', 'تحدد خطة اتصال ونشر متكاملة الرسائل الرئيسية والروزنامة، وتُدار جلسات اللجنة التوجيهية بحيث يُسجَّل كل قرار ويُسنَد إلى مسؤول ويُتابَع.', '01M4D6CAH5PG0GZ86833HGXMP4', NULL, 'on_track', '2025-01-01', '2030-12-31', NULL, NULL, NULL, NULL, 16, 'EnviroAI Programme Strategy, illustrative data', 1, '2026-10-08T07:24:25.930Z', '2026-10-08T07:24:25.930Z'),
('01M4D6CAYAG120NABQ9RES14C6', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAY712J87RZBWHJSWQDZ', 'output', 'G1.IO1.OP1', 'Updated results framework manual and templates', 'دليل إطار النتائج المحدّث ونماذجه', 'A revised manual covering the full results chain from strategic goals to activities, issued in both languages with ready to use templates for strategy documents, indicator cards, implementation plans and risk registers.', 'دليل منقّح يغطي سلسلة النتائج كاملة من الأهداف الاستراتيجية إلى الأنشطة، يصدر باللغتين مصحوباً بنماذج جاهزة للاستخدام لوثائق الاستراتيجيات وبطاقات المؤشرات والخطط التنفيذية وسجلات المخاطر.', '01M4D6CAGYP0HZ6XYMWHB2BYZT', NULL, 'on_track', '2025-01-01', '2030-12-31', NULL, NULL, NULL, NULL, 17, 'EnviroAI Programme Strategy, illustrative data', 1, '2026-10-08T07:24:25.930Z', '2026-10-08T07:24:25.930Z'),
('01M4D6CAYB43BFQ02D9GWYH35F', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAY712J87RZBWHJSWQDZ', 'output', 'G1.IO1.OP2', 'Planning capability programme for entity programme teams', 'برنامج تنمية قدرات التخطيط لفرق البرامج في الجهات', 'A certified training and coaching programme that builds results based planning skills in the programme teams of entities, with practical clinics held while strategies are being drafted.', 'برنامج تدريب وإرشاد معتمد يبني مهارات التخطيط القائم على النتائج لدى فرق البرامج في الجهات، مع عيادات تطبيقية تُعقد أثناء صياغة الاستراتيجيات.', '01M4D6CAH58AFT3SG1CKSBAGCW', NULL, 'on_track', '2025-01-01', '2030-12-31', NULL, NULL, NULL, NULL, 18, 'EnviroAI Programme Strategy, illustrative data', 1, '2026-10-08T07:24:25.931Z', '2026-10-08T07:24:25.931Z'),
('01M4D6CAYBKCPG0BNSPKTV0QMJ', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAY712J87RZBWHJSWQDZ', 'output', 'G1.IO1.OP3', 'Quality assured reviews of sector and entity strategies', 'مراجعات مضمونة الجودة لاستراتيجيات القطاعات والجهات', 'A technical review service that scores each submitted strategy against a published checklist, returns written findings and confirms alignment with the National Environment Strategy before adoption.', 'خدمة مراجعة فنية تقيّم كل استراتيجية مرفوعة وفق قائمة تحقق معلنة، وتعيد ملاحظات مكتوبة، وتؤكد المواءمة مع الاستراتيجية الوطنية للبيئة قبل الاعتماد.', '01M4D6BGEM8CD2PD6VB691TCQP', NULL, 'on_track', '2025-01-01', '2030-12-31', NULL, NULL, NULL, NULL, 19, 'EnviroAI Programme Strategy, illustrative data', 1, '2026-10-08T07:24:25.931Z', '2026-10-08T07:24:25.931Z'),
('01M4D6CAYBQRGJE9SVFJ5FSAE2', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAY8X9J4QD2PVHVKD2ZE', 'output', 'G1.IO2.OP1', 'NES monitoring framework and reporting cycle', 'إطار متابعة الاستراتيجية الوطنية للبيئة ودورة الإبلاغ', 'A monitoring framework with defined indicators, evidence requirements and a fixed reporting cycle, so that every initiative reports in the same way and on the same dates.', 'إطار متابعة بمؤشرات محددة ومتطلبات أدلة ودورة إبلاغ ثابتة، بحيث تبلّغ كل مبادرة بالطريقة نفسها وفي المواعيد نفسها.', '01M4D6BGEN0X0HZVKB2P6E6678', NULL, 'on_track', '2025-01-01', '2030-12-31', NULL, NULL, NULL, NULL, 20, 'EnviroAI Programme Strategy, illustrative data', 1, '2026-10-08T07:24:25.931Z', '2026-10-08T07:24:25.931Z'),
('01M4D6CAYBDJ47T2GB2QPF40XH', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAY8X9J4QD2PVHVKD2ZE', 'output', 'G1.IO2.OP2', 'Implementation support packages for lagging initiatives', 'حزم دعم التنفيذ للمبادرات المتأخرة', 'Targeted support for initiatives that fall behind: a diagnosis of blockers, a recovery plan with owners and dates, and a named support officer who stays with the initiative until it is back on track.', 'دعم موجّه للمبادرات المتأخرة: تشخيص للعوائق، وخطة تعافٍ بمسؤولين ومواعيد، وضابط دعم مسمّى يرافق المبادرة حتى تعود إلى المسار.', '01M4D6CAH2PKKDJ4K58DZVRRNW', NULL, 'on_track', '2025-01-01', '2030-12-31', NULL, NULL, NULL, NULL, 21, 'EnviroAI Programme Strategy, illustrative data', 1, '2026-10-08T07:24:25.931Z', '2026-10-08T07:24:25.931Z'),
('01M4D6CAYBDVBKA1XDK8TVR4RH', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAY8X9J4QD2PVHVKD2ZE', 'output', 'G1.IO2.OP3', 'Integrated delivery dashboard for leadership', 'لوحة متابعة تنفيذية متكاملة للقيادة', 'One dashboard that brings progress, risks, indicators and evidence status together for leadership, refreshed on the reporting cycle and drillable down to the initiative.', 'لوحة واحدة تجمع التقدم والمخاطر والمؤشرات وحالة الأدلة للقيادة، وتُحدَّث وفق دورة الإبلاغ ويمكن التعمق منها حتى مستوى المبادرة.', '01M4D6BGEN0X0HZVKB2P6E6678', NULL, 'on_track', '2025-01-01', '2030-12-31', NULL, NULL, NULL, NULL, 22, 'EnviroAI Programme Strategy, illustrative data', 1, '2026-10-08T07:24:25.931Z', '2026-10-08T07:24:25.931Z'),
