('01M4D6CAZ94PVZJE7RDF5K13FE', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAYCK2WSFXKMRHSK2YA0', 'project', 'CP-17', 'Environmental data quality assurance framework', 'إطار ضمان جودة البيانات البيئية', 'Defines the quality dimensions, checks and sign off rules that every environmental dataset of the Office must pass before release. The framework is aligned with international data quality guidance and applies to monitoring, administrative and survey sources.', 'يحدد أبعاد الجودة والفحوص وقواعد الاعتماد التي يجب أن تجتازها كل مجموعة بيانات بيئية لدى المكتب قبل إصدارها. ويتوافق الإطار مع الإرشادات الدولية لجودة البيانات ويسري على مصادر الرصد والسجلات الإدارية والمسوح.', '01M4D6CAH4W5AVSABK3GFKSWC9', '01M4D6BHEST5ZXVWHEEFMYH70F', 'on_track', '2026-08-01', '2028-03-31', 1900000.0, '{"people":9,"systems_en":["Quality Assessment Register","Environmental Metadata Repository"],"systems_ar":["سجل تقييم الجودة","مستودع البيانات الوصفية البيئية"],"note_en":"Consumes international quality guidance, current release practices, and quality leads from each data producing unit.","note_ar":"يستهلك الإرشادات الدولية للجودة وممارسات الإصدار الحالية ومسؤولي الجودة في كل وحدة منتجة للبيانات."}', 5, 3, 114, 'EnviroAI Programme Strategy, illustrative data', 1, '2026-10-08T07:24:25.961Z', '2026-10-08T07:24:25.961Z'),
