('01M4D6CAZD5K32C22V2CMRR821', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAYCRD8SVXCS1B3SH1YT', 'project', 'CP-20', 'Modernisation of field monitoring and sensor data capture', 'تحديث الرصد الميداني والتقاط بيانات المستشعرات', 'Moves field teams from paper and spreadsheets to mobile capture with validation at source, and connects station and sensor feeds to the production platform. It covers water, air and land monitoring in the first phase.', 'ينقل الفرق الميدانية من الورق والجداول الإلكترونية إلى التقاط البيانات عبر الأجهزة المحمولة مع التحقق من المصدر، ويربط تغذيات المحطات والمستشعرات بمنصة الإنتاج. ويشمل رصد المياه والهواء والأراضي في المرحلة الأولى.', '01M4D6BGEJJ8DT77CSYCK82ZBV', '01M4D6BHEP9TW2034D56782GZ9', 'on_track', '2025-10-01', '2026-11-30', 4600000.0, '{"people":10,"systems_en":["Field Data Collection System","Environmental Data Production Platform"],"systems_ar":["نظام جمع البيانات الميدانية","منصة إنتاج البيانات البيئية"],"note_en":"Consumes mobile devices, a field data capture application, sensor interface specifications, and field team training.","note_ar":"يستهلك أجهزة محمولة وتطبيقا لالتقاط البيانات الميدانية ومواصفات واجهات المستشعرات وتدريب الفرق الميدانية."}', 4, 4, 127, 'EnviroAI Programme Strategy, illustrative data', 1, '2026-10-08T07:24:25.965Z', '2026-10-08T07:24:25.965Z'),
