('01M4D6CB0722V8SANA6H08NQA6', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAYGYZ80M4QXZQNEWKEW', 'project', 'CP-41', 'Internal performance reporting cockpit', 'لوحة الأداء الداخلي للمكتب', 'A management cockpit that reports the Office''s own performance, including delivery, budget, people and service levels, from the operational systems. Delayed because source data in finance and human resources is not yet consistent.', 'لوحة إدارية تعرض أداء المكتب نفسه، ويشمل التنفيذ والميزانية والكوادر ومستويات الخدمة، من الأنظمة التشغيلية. وتأخرت لأن بيانات المصدر في المالية والموارد البشرية لم تتسق بعد.', '01M4D6CAH58S164TAB88ATBPNN', '01M4D6BHERXH0T9A327SBQDQP6', 'delayed', '2025-07-01', '2027-01-31', 1150000.0, '{"people":5,"systems_en":["Delivery Dashboard","Financial Management System","Human Resources System"],"systems_ar":["لوحة التنفيذ","نظام الإدارة المالية","نظام الموارد البشرية"],"note_en":"Consumes extracts from the finance, human resources and service desk systems.","note_ar":"يستهلك استخراجات من أنظمة المالية والموارد البشرية ومكتب الخدمة."}', 2, 3, 212, 'EnviroAI Programme Strategy, illustrative data', 1, '2026-10-08T07:24:25.991Z', '2026-10-08T07:24:25.991Z'),
