INSERT INTO "council_risks" ("id", "strategy_id", "node_id", "code", "title_en", "title_ar", "description_en", "description_ar", "likelihood", "impact", "owner_user_id", "mitigation_en", "mitigation_ar", "status", "created_at", "updated_at") VALUES
('01M4D6CBDDXHN7CQ66PCM190Z5', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAY8X9J4QD2PVHVKD2ZE', 'R-01', 'Entities submit progress data late or incomplete', 'تأخر الجهات في رفع بيانات التقدم أو نقصها', 'Quarterly progress submissions from entities arrive after the consolidation window or without the supporting evidence, so the national delivery picture is built on partial returns and has to be revised after publication.', 'تصل تقارير التقدم الربعية من الجهات بعد نافذة التجميع أو من دون الأدلة الداعمة، فتُبنى صورة الإنجاز الوطني على بيانات ناقصة ويُضطر المكتب إلى تعديلها بعد النشر.', 5, 4, '01M4D6BHET7Q90XBQ6PJ0SVCCM', 'Publish a binding reporting calendar with an automated reminder sequence, give each entity a named implementation support officer, and report submission compliance by entity to the Programme Steering Committee alongside the progress figures.', 'إصدار روزنامة ملزمة لرفع التقارير مع سلسلة تذكيرات آلية، وتخصيص ضابط دعم تنفيذ مسمّى لكل جهة، ورفع مستوى الالتزام بالرفع لكل جهة إلى اللجنة التوجيهية للبرنامج إلى جانب أرقام التقدم.', 'open', '2026-10-08T07:24:26.413Z', '2026-10-08T07:24:26.413Z'),
('01M4D6CBDDAQM33Y92GJRFMC9R', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAYGS28BST7FX2WS3817', 'R-02', 'Cyber incident exposing sensitive environmental data', 'حادثة سيبرانية تكشف بيانات بيئية حساسة', 'An intrusion or a mishandled transfer exposes restricted records held for analysis, such as facility level compliance data or licensing records, breaching the confidentiality terms under which entities share them.', 'اختراق أو نقل خاطئ يكشف سجلات مقيّدة محتفظاً بها للتحليل، مثل بيانات الامتثال على مستوى المنشآت أو سجلات التراخيص، بما يخل بشروط السرية التي تشارك الجهات بياناتها بموجبها.', 2, 5, '01M4D6BHEQ32QCSD0FWQPS6A3W', 'Segregate the restricted data environment with no external egress, enforce role based access with quarterly recertification, encrypt every transfer, and run an annual breach simulation with the incident response team.', 'عزل بيئة البيانات المقيّدة دون منافذ خروج خارجية، وتطبيق صلاحيات قائمة على الأدوار مع إعادة اعتماد ربعية، وتشفير كل عملية نقل، وإجراء محاكاة سنوية للاختراق مع فريق الاستجابة للحوادث.', 'mitigating', '2026-10-08T07:24:26.413Z', '2026-10-08T07:24:26.413Z'),
('01M4D6CBDD31BJ84D887VYJF27', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAY6R3SYHXXXG7N8R26H', 'R-03', 'Loss of specialist data and modelling staff', 'فقدان الكوادر المتخصصة في البيانات والنمذجة', 'Experienced staff in environmental accounts, remote sensing and quantitative modelling leave for better paid roles, and the methods they hold personally are not documented well enough for a successor to continue without a gap.', 'يغادر أصحاب الخبرة في الحسابات البيئية والاستشعار عن بعد والنمذجة الكمية إلى وظائف أعلى أجراً، ولا تكون المنهجيات التي يحتفظون بها شخصياً موثقة بما يكفي ليواصل خلفهم العمل دون انقطاع.', 4, 4, '01M4D6BHETF9W8SQHJXQS8JBQT', 'Run a retention review for critical roles with the Human Resources department, require a documented method file and a named deputy for every data product, and build a standing pool of trained successors through capability development.', 'إجراء مراجعة للاحتفاظ بالأدوار الحرجة مع إدارة الموارد البشرية، واشتراط ملف منهجية موثق ونائب مسمّى لكل منتج بيانات، وبناء رصيد دائم من الخلفاء المدرَّبين عبر إدارة تنمية القدرات.', 'mitigating', '2026-10-08T07:24:26.413Z', '2026-10-08T07:24:26.413Z'),
('01M4D6CBDEXC0ZE9EV735CQCTJ', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAYCRD8SVXCS1B3SH1YT', 'R-04', 'Data systems modernisation overruns', 'تجاوز مشروع تحديث نظم البيانات للمدة والكلفة', 'The replacement of the environmental data production platform slips beyond its planned window, forcing teams to run the old and new systems in parallel and delaying the releases that depend on the migration.', 'يتأخر استبدال منصة إنتاج البيانات البيئية عن نافذته المخططة، فتضطر الفرق إلى تشغيل النظامين القديم والجديد بالتوازي وتتأخر الإصدارات المعتمدة على الترحيل.', 3, 4, '01M4D6BHERFH5W492CXYXGVM1G', 'Migrate one data domain at a time with a tested rollback for each, hold release dates on the legacy system until the new one has produced two clean cycles, and review the vendor plan monthly against milestones.', 'ترحيل مجال بيانات واحد في كل مرة مع خطة تراجع مجرّبة لكل منها، والإبقاء على مواعيد الإصدار على النظام القديم حتى ينتج الجديد دورتين سليمتين، ومراجعة خطة المورّد شهرياً قياساً بالمراحل.', 'open', '2026-10-08T07:24:26.414Z', '2026-10-08T07:24:26.414Z'),
('01M4D6CBDEH1DAGS35EDWHET39', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAYD147H9ZW72ZFV1M4Z', 'R-05', 'Data sharing agreements stall on legal grounds', 'تعثر اتفاقيات تبادل البيانات لأسباب نظامية', 'Entities decline or delay signature because their own rules restrict disclosure, so priority administrative sources remain unavailable and costly separate collection continues.', 'ترفض جهات التوقيع أو تؤجله لأن أنظمتها تقيّد الإفصاح، فتظل مصادر البيانات الإدارية ذات الأولوية غير متاحة ويستمر جمع منفصل مرتفع الكلفة.', 4, 3, '01M4D6BHEQKPFW1H83BFHK8QB8', 'Issue a standard agreement cleared in advance by legal advisers, offer a restricted access tier for sensitive fields, and escalate the remaining cases through the Data Governance Board rather than bilaterally.', 'إصدار اتفاقية نموذجية يُجاز نصها مسبقاً من المستشارين القانونيين، وإتاحة مستوى وصول مقيّد للحقول الحساسة، ورفع الحالات المتبقية عبر مجلس حوكمة البيانات بدل المعالجة الثنائية.', 'open', '2026-10-08T07:24:26.414Z', '2026-10-08T07:24:26.414Z'),
('01M4D6CBDE99YFSN58NJVWT2BG', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAY8EQ6JVSKMY8W56F99', 'R-06', 'Gaps in field monitoring coverage and response', 'فجوات في تغطية الرصد الميداني والاستجابة له', 'Monitoring stations, field surveys and reporting entities cover less ground, or respond less completely, than planned, which raises uncertainty, forces heavier estimation and weakens confidence in the published figures.', 'تغطي محطات الرصد والمسوح الميدانية والجهات المبلِّغة نطاقاً أقل مما هو مخطط، أو تستجيب بصورة أقل اكتمالاً، مما يرفع عدم اليقين ويفرض تقديراً أكبر ويضعف الثقة في الأرقام المنشورة.', 3, 4, '01M4D6BHEQP10YDP9M2S6Q22GQ', 'Combine ground measurement with satellite and administrative sources where they are available, simplify reporting templates, and tell reporting entities how their data is protected and used.', 'الجمع بين القياس الميداني ومصادر الأقمار الصناعية والبيانات الإدارية متى توفرت، وتبسيط نماذج الإبلاغ، وإعلام الجهات المبلِّغة بكيفية حماية بياناتها واستخدامها.', 'mitigating', '2026-10-08T07:24:26.414Z', '2026-10-08T07:24:26.414Z'),
('01M4D6CBDEN8N813ECVTF4YXNE', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAY743SM5Q85A348YH1Q', 'R-07', 'Foresight products do not reach decisions', 'عدم وصول منتجات الاستشراف إلى القرار', 'Scenario sets and scanning reports are circulated but arrive outside the planning and budget calendar, so they inform discussion without changing any commitment.', 'تُوزَّع مجموعات السيناريوهات وتقارير المسح لكنها تصل خارج روزنامة التخطيط والموازنة، فتثري النقاش دون أن تغيّر أي التزام.', 3, 3, '01M4D6BHETEQ14RFJ4M9ZHBW8N', 'Fix the foresight calendar to the planning and budget cycle, require a foresight annex in every sector strategy review, and close each briefing with named decisions and owners rather than with a discussion.', 'ربط روزنامة الاستشراف بدورة التخطيط والموازنة، واشتراط ملحق استشرافي في كل مراجعة لاستراتيجية قطاعية، وإنهاء كل إحاطة بقرارات ومسؤولين مسمّين لا بنقاش.', 'open', '2026-10-08T07:24:26.414Z', '2026-10-08T07:24:26.414Z'),
('01M4D6CBDEMEN12KH9FXWRJFX6', '01M4D6CAY5T0XKCNYRFK5B2F2D', NULL, 'R-08', 'Mid cycle reduction of the Programme Office budget', 'خفض موازنة مكتب البرنامج في منتصف الدورة', 'A fiscal correction cuts the operating and capital envelope during the strategy period, which would stop the systems modernisation and the monitoring programme at the same time.', 'تخفض مراجعة مالية سقف الإنفاق التشغيلي والرأسمالي خلال فترة الاستراتيجية، مما قد يوقف تحديث النظم وبرنامج الرصد في آن واحد.', 1, 5, '01M4D6BHEQP10YDP9M2S6Q22GQ', 'Maintain a ranked list of projects with the minimum viable scope of each, agree the core monitoring programme as a protected line with the Ministry of Finance, and phase contracts so that commitments can be paused at defined points.', 'الاحتفاظ بقائمة مرتبة للمشاريع مع الحد الأدنى القابل للتنفيذ من كل منها، والاتفاق مع وزارة المالية على برنامج الرصد الأساسي بوصفه بنداً محمياً، وتجزئة العقود بحيث يمكن إيقاف الالتزامات عند نقاط محددة.', 'open', '2026-10-08T07:24:26.414Z', '2026-10-08T07:24:26.414Z'),
('01M4D6CBDE7849CEQBRTGEN3A3', '01M4D6CAY5T0XKCNYRFK5B2F2D', NULL, 'R-09', 'Shift in national priorities forces re-planning', 'تغير الأولويات الوطنية يفرض إعادة التخطيط', 'A change in national direction or an urgent environmental mandate, such as a drought response, redirects the Office''s capacity to unplanned work, and the institutional strategy is quietly deprioritised while the new demand is served.', 'يؤدي تغير التوجه الوطني أو تكليف بيئي عاجل، كالاستجابة للجفاف، إلى تحويل طاقة المكتب نحو عمل غير مخطط، فتتراجع الاستراتيجية المؤسسية بهدوء في سلّم الأولويات أثناء تلبية الطلب الجديد.', 3, 4, '01M4D6BHETEQ14RFJ4M9ZHBW8N', 'Reserve a defined share of departmental capacity for unplanned national tasking, and require the steering committee to record formally which targets are deferred whenever new work is absorbed.', 'تخصيص حصة محددة من طاقة الإدارات للتكليفات الوطنية غير المخططة، واشتراط أن تسجّل اللجنة التوجيهية رسمياً المستهدفات المؤجلة كلما استُوعب عمل جديد.', 'open', '2026-10-08T07:24:26.414Z', '2026-10-08T07:24:26.414Z'),
('01M4D6CBDEACEVY7T895R5KJJC', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAYAG120NABQ9RES14C6', 'R-10', 'The results framework manual is adopted formally but not in practice', 'اعتماد دليل إطار النتائج شكلياً دون تطبيق فعلي', 'Entities fill in the new templates while keeping their old habit of listing activities as objectives, so documents look compliant and the results chain behind them remains broken.', 'تملأ الجهات النماذج الجديدة مع إبقاء عادتها القديمة في سرد الأنشطة بوصفها أهدافاً، فتبدو الوثائق ملتزمة وتبقى سلسلة النتائج خلفها مكسورة.', 4, 2, '01M4D6BHF5P3APCFERZJRH5MJR', 'Score every submitted strategy against a published quality checklist, return non compliant documents with written findings, and pair the manual with coaching clinics for entity planning teams during drafting.', 'تقييم كل استراتيجية مرفوعة وفق قائمة تحقق معلنة للجودة، وإعادة الوثائق غير المستوفية مع ملاحظات مكتوبة، وربط الدليل بعيادات إرشاد لفرق التخطيط في الجهات أثناء الصياغة.', 'mitigating', '2026-10-08T07:24:26.414Z', '2026-10-08T07:24:26.414Z'),
('01M4D6CBDEER24P1H7DK870XAY', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAY9CRAK625681WJ2DSV', 'R-11', 'Unofficial figures compete with official environmental data', 'منافسة الأرقام غير الرسمية للبيانات البيئية الرسمية', 'Entities, consultancies and media publish their own estimates for the same phenomena, and users are left with several numbers and no way to tell which is authoritative.', 'تنشر الجهات وشركات الاستشارات ووسائل الإعلام تقديراتها الخاصة للظواهر نفسها، فيجد المستخدمون أمامهم أرقاماً متعددة ولا سبيل لمعرفة أيها المرجع.', 5, 2, '01M4D6BHETF9W8SQHJXQS8JBQT', 'Publish an official data mark and a single reference page per indicator, shorten release lag so the official figure arrives first, and agree a clearance rule with entities before any national figure is released.', 'إصدار علامة للبيانات الرسمية وصفحة مرجعية واحدة لكل مؤشر، وتقصير فجوة النشر ليصل الرقم الرسمي أولاً، والاتفاق مع الجهات على قاعدة إجازة قبل إصدار أي رقم وطني.', 'open', '2026-10-08T07:24:26.415Z', '2026-10-08T07:24:26.415Z'),
('01M4D6CBDFJ8MZVG5DYM0Y8CZR', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAYFRY6ZXVVYV2BJYWBX', 'R-12', 'Low adoption of the digital workplace', 'ضعف تبني بيئة العمل الرقمية', 'Staff continue to work through email attachments and personal spreadsheets after the new platform is delivered, so the promised single version of a document never materialises.', 'يواصل الموظفون العمل عبر مرفقات البريد والجداول الشخصية بعد تسليم المنصة الجديدة، فلا تتحقق النسخة الواحدة الموعودة للوثيقة.', 3, 2, '01M4D6BHF843YQERMTDQX9X22N', 'Move the processes that matter most to each department first, retire the old channel for those processes on a published date, and track adoption per department in the monthly focal points meeting.', 'نقل العمليات الأهم في كل إدارة أولاً، وإيقاف القناة القديمة لتلك العمليات في تاريخ معلن، ومتابعة التبني لكل إدارة في اجتماع ضباط الاتصال الشهري.', 'mitigating', '2026-10-08T07:24:26.415Z', '2026-10-08T07:24:26.415Z'),
('01M4D6CBDFDRTB43T90DZ58BZ2', '01M4D6CAY5T0XKCNYRFK5B2F2D', NULL, 'R-13', 'Dependence on a single vendor for analytics platforms', 'الاعتماد على مورّد وحيد لمنصات التحليل', 'Several reporting and analytics products rest on one supplier''s stack, which concentrates renewal risk and limits the Office''s room to negotiate or to move.', 'تعتمد عدة منتجات للتقارير والتحليل على حزمة مورّد واحد، مما يركّز مخاطر التجديد ويحدّ من مساحة المكتب للتفاوض أو للانتقال.', 2, 3, '01M4D6BHET7Q90XBQ6PJ0SVCCM', 'Keep all source data and transformation logic inside stores owned by the Office, require export in open formats in every contract, and stagger renewal dates so no two critical platforms expire together.', 'إبقاء كل البيانات المصدرية ومنطق التحويل داخل مخازن يملكها المكتب، واشتراط التصدير بصيغ مفتوحة في كل عقد، وتوزيع مواعيد التجديد بحيث لا تنتهي منصتان حرجتان معاً.', 'open', '2026-10-08T07:24:26.415Z', '2026-10-08T07:24:26.415Z'),
('01M4D6CBDFDB780F7332A478WA', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAYGMK74PX81YNDAWTX3', 'R-14', 'Late submissions to international indicator bodies', 'التأخر في الرفع إلى جهات المؤشرات الدولية', 'A national data return misses an international compilation deadline, and Saudi Arabia is shown with an older figure or with an estimate produced by the compiling organisation.', 'تفوت بيانات وطنية موعد تجميع دولياً، فتظهر المملكة بأرقام أقدم أو بتقدير تعدّه المنظمة المجمِّعة.', 2, 2, '01M4D6BHF843YQERMTDQX9X22N', 'Maintain a calendar of every international submission with an owner and a two week buffer, and pre clear recurring returns with the source entities at the start of each year.', 'الاحتفاظ بروزنامة لكل رفع دولي مع مسؤول وهامش أسبوعين، وإجازة التقارير المتكررة مسبقاً مع الجهات المصدرية في مطلع كل عام.', 'open', '2026-10-08T07:24:26.415Z', '2026-10-08T07:24:26.415Z'),
('01M4D6CBDF2YAZEH71P5H7C720', '01M4D6CAY5T0XKCNYRFK5B2F2D', NULL, 'R-15', 'Turnover in the department focal points network', 'دوران أعضاء شبكة ضباط الاتصال في الإدارات', 'Focal points change frequently and their replacements arrive without induction, so data quality in the strategy system drops and the Strategy Office absorbs the correction work.', 'يتغير ضباط الاتصال بكثرة ويصل بدلاؤهم دون تهيئة، فتنخفض جودة البيانات في منظومة الاستراتيجية ويتحمل مكتب الاستراتيجية عبء التصحيح.', 4, 2, '01M4D6BHETEQ14RFJ4M9ZHBW8N', 'Name a deputy focal point in every department, publish a one hour induction pack and a short guide, and require a handover note before any focal point is replaced.', 'تسمية نائب لضابط الاتصال في كل إدارة، ونشر حزمة تهيئة مدتها ساعة ودليل موجز، واشتراط مذكرة تسليم قبل استبدال أي ضابط اتصال.', 'open', '2026-10-08T07:24:26.415Z', '2026-10-08T07:24:26.415Z'),
('01M4D6CBDFA3TR6XG9YEF3JB1M', '01M4D6CAY5T0XKCNYRFK5B2F2D', NULL, 'R-16', 'Business continuity arrangements untested', 'عدم اختبار ترتيبات استمرارية الأعمال', 'Continuity plans exist on paper but have not been exercised against a real disruption, so recovery times for the data release chain and the leadership dashboard are unproven.', 'توجد خطط الاستمرارية على الورق لكنها لم تُجرَّب أمام تعطل فعلي، فتبقى أزمنة التعافي لسلسلة إصدار البيانات ولوحة القيادة غير مثبتة.', 2, 4, '01M4D6BHEQP10YDP9M2S6Q22GQ', 'Run two continuity exercises a year covering a data centre failure and the loss of a key system, publish the recovery times achieved, and close every gap found with a dated action.', 'إجراء تمرينين للاستمرارية سنوياً يغطيان تعطل مركز البيانات وفقدان نظام رئيسي، ونشر أزمنة التعافي المتحققة، وإغلاق كل فجوة تُكتشف بإجراء مؤرخ.', 'mitigating', '2026-10-08T07:24:26.415Z', '2026-10-08T07:24:26.415Z'),
('01M4D6CBDFTRRMWFPSWM75CJDS', '01M4D6CAY5T0XKCNYRFK5B2F2D', '01M4D6CAYCZ259J2BP2JT3Z953', 'R-17', 'Policy lab trials return inconclusive results', 'خروج تجارب مختبر السياسات بنتائج غير حاسمة', 'A behavioural or policy trial is run on too small a sample or without a clean comparison group, so the finding cannot support a recommendation either way.', 'تُجرى تجربة سلوكية أو سياساتية على عينة صغيرة أو دون مجموعة مقارنة نظيفة، فلا تدعم النتيجة أي توصية في أي اتجاه.', 2, 2, '01M4D6BHEVMQK6SR4J1Y8T08WK', 'Require a pre registered design with a power calculation before any trial starts, and publish null results as findings so that the learning is kept rather than repeated.', 'اشتراط تصميم مسجّل مسبقاً مع حساب القوة الإحصائية قبل بدء أي تجربة، ونشر النتائج الصفرية بوصفها مخرجات حتى يُحفظ التعلم ولا يتكرر.', 'open', '2026-10-08T07:24:26.415Z', '2026-10-08T07:24:26.415Z'),
('01M4D6CBDFD7VC90V99F61EW7Z', '01M4D6CAY5T0XKCNYRFK5B2F2D', NULL, 'R-18', 'Misinterpretation of environmental figures in public coverage', 'إساءة تفسير الأرقام البيئية في التغطية العامة', 'A release is reported without its definitions or its revision status, a misleading headline spreads, and the Office spends the following weeks correcting the record instead of explaining the substance.', 'يُنقل إصدار دون تعريفاته أو حالة مراجعته، فينتشر عنوان مضلل، ويقضي المكتب الأسابيع التالية في تصحيح السجل بدل شرح المضمون.', 3, 2, '01M4D6BHETF9W8SQHJXQS8JBQT', 'Issue a plain language summary and a chart pack with every major release, brief editors ahead of sensitive publications, and keep a standing correction procedure with a named spokesperson.', 'إصدار ملخص بلغة مبسطة وحزمة رسوم مع كل إصدار رئيسي، وإحاطة المحررين قبل المنشورات الحساسة، والاحتفاظ بإجراء تصحيح دائم مع متحدث مسمّى.', 'open', '2026-10-08T07:24:26.416Z', '2026-10-08T07:24:26.416Z'),
('01M4D6CBDGSEFJ6FFTDT9H2SDB', '01M4D6CAY5T0XKCNYRFK5B2F2D', NULL, 'R-19', 'Disruption from the office relocation', 'اضطراب ناتج عن الانتقال إلى المقر الجديد', 'The move of departments to the new premises during 2025 was expected to interrupt monitoring operations and the release schedule for several weeks.', 'كان يُتوقع أن يعطّل انتقال الإدارات إلى المقر الجديد خلال عام 2025 عمليات الرصد وجدول الإصدار لعدة أسابيع.', 1, 1, '01M4D6BHETEQ14RFJ4M9ZHBW8N', 'The move was phased outside the release peaks with remote working kept available throughout, and no release date was missed, so the risk was closed after the final department relocated.', 'جرى الانتقال على مراحل خارج ذرى الإصدار مع إبقاء العمل عن بُعد متاحاً طوال الوقت، ولم يفُت أي موعد إصدار، فأُغلقت المخاطرة بعد انتقال آخر إدارة.', 'closed', '2026-10-08T07:24:26.416Z', '2026-10-08T07:24:26.416Z'),
('01M4D6CBDGNEW27PSQ2MA6B579', '01M4D6CAY5T0XKCNYRFK5B2F2D', NULL, 'R-20', 'Delay in approving the institutional strategy', 'تأخر اعتماد الاستراتيجية المؤسسية', 'Approval of the strategy was at risk of slipping past the start of the 2025 planning year, which would have left departments planning against an unapproved results chain.', 'كان اعتماد الاستراتيجية معرّضاً للتأخر عن بداية سنة التخطيط 2025، مما كان سيترك الإدارات تخطط وفق سلسلة نتائج غير معتمدة.', 1, 2, '01M4D6BHETF9W8SQHJXQS8JBQT', 'The draft was reviewed with the sectors ahead of submission and approved on 16 March 2025, and departmental plans were aligned within the same quarter, so the risk was closed.', 'روجعت المسودة مع القطاعات قبل رفعها واعتُمدت في 16 مارس 2025، ووُوئمت خطط الإدارات في الربع نفسه، فأُغلقت المخاطرة.', 'closed', '2026-10-08T07:24:26.416Z', '2026-10-08T07:24:26.416Z');
INSERT INTO "council_strategies" ("id", "name_en", "name_ar", "period_from", "period_to", "vision_en", "vision_ar", "mission_en", "mission_ar", "values_json", "status", "is_default", "approved_on", "source_document_id", "owner_unit_id", "is_illustrative", "created_at", "updated_at") VALUES
('01M4D6CAY5T0XKCNYRFK5B2F2D', 'Programme Office Institutional Strategy 2025 to 2030', 'الاستراتيجية المؤسسية لمكتب البرنامج 2025 - 2030', '2025-01-01', '2030-12-31', 'A reference institution whose strategy, environmental data and foresight set the professional standard for environment, water and agriculture work in Saudi Arabia.', 'مؤسسة مرجعية تضع استراتيجيتها وبياناتها البيئية واستشرافها المعيار المهني لأعمال البيئة والمياه والزراعة في المملكة العربية السعودية.', 'We steer the National Environment Strategy, monitor its delivery, keep environmental data trustworthy and read the future, so that choices on water, food, climate, land, waste and air rest on evidence rather than assumption. We work alongside every entity in the sector, and with partners in universities, the private sector and the community, to turn national priorities into plans that are delivered and measured.', 'نقود الاستراتيجية الوطنية للبيئة ونتابع تنفيذها، ونحافظ على موثوقية البيانات البيئية ونستشرف المستقبل، لتستند الخيارات في المياه والغذاء والمناخ والأراضي والنفايات والهواء إلى الأدلة لا إلى الافتراضات. ونعمل جنباً إلى جنب مع جهات القطاع كافة، ومع شركائنا في الجامعات والقطاع الخاص والمجتمع، لتحويل الأولويات الوطنية إلى خطط قابلة للتنفيذ والقياس.', '[{"name_en":"Evidence first","name_ar":"الأدلة أولاً","description_en":"Every recommendation we issue rests on data whose source can be traced and a method that can be explained to anyone who asks. Where the evidence is thin we say so plainly instead of closing the gap with opinion.","description_ar":"تستند كل توصية نصدرها إلى بيانات يمكن تتبع مصدرها ومنهجية يمكن شرحها لكل من يسأل عنها. وحين تكون الأدلة ضعيفة نُصرّح بذلك بوضوح بدل سدّ الفجوة بالانطباعات."},{"name_en":"Professional independence","name_ar":"الاستقلالية المهنية","description_en":"We publish assessments and figures as the data reads them, without softening a message to suit any party. That independence is precisely what makes our work usable by everyone.","description_ar":"ننشر التقييمات والأرقام كما تدل عليها البيانات، دون تطويع الرسالة لصالح أي جهة. وهذه الاستقلالية هي بالذات ما يجعل عملنا صالحاً للاستخدام لدى الجميع."},{"name_en":"Partnership in delivery","name_ar":"الشراكة في التنفيذ","description_en":"We do not hand a plan over and step away; we sit with the entity that carries it until the obstacles are named and cleared. Our success is measured by what the sector delivers, not by the number of documents we issue.","description_ar":"لا نُسلّم الخطة ثم ننصرف، بل نجلس مع الجهة المنفذة حتى تُحدَّد العوائق وتُذلَّل. ويُقاس نجاحنا بما يُنجزه القطاع لا بعدد الوثائق التي نُصدرها."},{"name_en":"Foresight as a habit","name_ar":"الاستشراف عادة مؤسسية","description_en":"We look past the current planning cycle and treat an early signal as work that begins today. Preparing for what is likely, and for what is merely possible, belongs in every plan we write.","description_ar":"ننظر إلى ما وراء دورة التخطيط الحالية ونتعامل مع الإشارة المبكرة بوصفها عملاً يبدأ اليوم. والاستعداد لما هو مرجّح، ولما هو ممكن فحسب، جزء أصيل من كل خطة نُعِدّها."},{"name_en":"Knowledge that stays","name_ar":"معرفة تبقى في المؤسسة","description_en":"What a colleague learns becomes an asset of the Office: recorded, findable and ready for the next team to reuse. We hand over knowledge deliberately so that a departure never costs us a capability.","description_ar":"ما يتعلمه الزميل يصبح أصلاً من أصول المكتب: موثقاً وقابلاً للاسترجاع وجاهزاً لإعادة استخدامه من الفريق التالي. ونُسلّم المعرفة بشكل منظم حتى لا يكلفنا خروج موظف فقدان قدرة مؤسسية."}]', 'live', 1, '2025-03-16', NULL, '01M4D6BGEM8CD2PD6VB691TCQP', 1, '2026-10-08T07:24:25.925Z', '2026-10-08T07:24:25.925Z');
